  column: NormalizedColumn<unknown>;
  className?: string;
}) {
  const table = useDataTableContext();
  const { labels } = table;
  if (!column.sortable || table.features.dragSort)
    return (
      <div className={cn("flex items-center", className)}>
        <HeaderTitle column={column} />
      </div>
    );
  const order = table.state.sort.find((item) => item.key === column.id)?.order;
  const sortBy = (next: SortOrder | undefined) =>
    table.setSort(next ? [{ key: column.id, order: next }] : []);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            size="sm"
            className={cn(
              "-ms-2 h-8 max-w-full gap-1 px-2 font-medium data-popup-open:bg-accent",
              className,
            )}
          />
        }
      >
        <HeaderTitle column={column} />
        <SortIcon order={order} />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className={menuWidth}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>{column.title}</DropdownMenuLabel>
        </DropdownMenuGroup>
        <DropdownMenuItem onClick={() => sortBy("asc")}>
          <ArrowUp />
          {labels.sortAscending}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => sortBy("desc")}>
          <ArrowDown />
          {labels.sortDescending}
        </DropdownMenuItem>
        {order && (
          <DropdownMenuItem onClick={() => sortBy(undefined)}>
            <X />
            {labels.clearSorting}
          </DropdownMenuItem>
        )}
        <DropdownMenuSeparator />
        <DropdownMenuItem
          onClick={() =>
            table.setColumnState((current) => ({
              ...current,
              visibility: { ...current.visibility, [column.id]: false },
            }))
          }
        >
          <EyeOff />
          {labels.hideColumn}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { CopyText } from "@/components/ui/copy-text";
import { LongText } from "@/components/ui/long-text";
import { isValidElement, type ReactNode } from "react";
import { getPath, isEmptyValue, toTime } from "@/components/ui/data-table/engine";
import type { DataTableLabels } from "@/components/ui/data-table/labels";
import type {
  DataTableColumn,
  DataTableDataColumn,
  DataTableDisplayColumn,
  DataTableOption,
  DataTableSearchType,
  DataTableValueType,
  NormalizedColumn,
} from "@/components/ui/data-table/types";

type Format = DataTableDataColumn<unknown>["format"];

interface FormatContext {
  readonly locale: string | undefined;
  readonly labels: DataTableLabels;
  readonly format: Format;
  readonly valueEnum?: readonly DataTableOption[];
}

function formatNumber(value: unknown, locale?: string, options?: Format) {
  const number = Number(value);
  if (Number.isNaN(number)) return String(value);
  return new Intl.NumberFormat(locale, options).format(number);
}

// toTime reads a calendar date as local midnight, so it formats as that day.
function formatDate(value: unknown, locale?: string, options?: Format) {
  const time = toTime(value);
  if (time === undefined) return String(value);
  return new Intl.DateTimeFormat(locale, options).format(time);
}

function optionLabel(value: unknown, options?: readonly DataTableOption[]) {
  return options?.find((option) => option.value === String(value));
}

/** Plain text of a value, shared by cells, chips and CSV exports. */
const textFormatters: Record<
  DataTableValueType,
  (value: unknown, context: FormatContext) => string
> = {
  text: (value) => String(value),
  number: (value, { locale, format }) => formatNumber(value, locale, format),
  money: (value, { locale, format }) =>
    formatNumber(value, locale, {
      style: "currency",
      currency: "USD",
      ...format,
    }),
  percent: (value, { locale, format }) =>
    formatNumber(Number(value) / 100, locale, {
      style: "percent",
      maximumFractionDigits: 2,
      ...format,
    }),
  date: (value, { locale, format }) =>
    formatDate(value, locale, format ?? { dateStyle: "medium" }),
  datetime: (value, { locale, format }) =>
    formatDate(
      value,
      locale,
      format ?? { dateStyle: "medium", timeStyle: "short" },
    ),
  enum: (value, { valueEnum }) => {
    const label = optionLabel(value, valueEnum)?.label;
    return typeof label === "string" ? label : String(value);
  },
  boolean: (value, { labels }) => (value ? labels.yes : labels.no),
};

export function formatValue(
  valueType: DataTableValueType,
  value: unknown,
  context: FormatContext,
) {
  if (isEmptyValue(value)) return "";
  return textFormatters[valueType](value, context);
}

function renderEnum(value: unknown, options?: readonly DataTableOption[]) {
  const option = optionLabel(value, options);
  if (!option) return String(value);
  return <Badge variant={option.color ?? "secondary"}>{option.label}</Badge>;
}

const defaultSearchTypes: Record<DataTableValueType, DataTableSearchType> = {
  text: "text",
  number: "numberRange",
  money: "numberRange",
  percent: "numberRange",
  date: "dateRange",
  datetime: "datetimeRange",
  enum: "select",
  boolean: "boolean",
};

/** The text inside a node, through elements such as a badge. */
function nodeText(node: ReactNode): string {
  if (node == null || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(nodeText).join("");
  if (isValidElement<{ children?: ReactNode }>(node))
    return nodeText(node.props.children);
  return "";
}

/** Filter controls list an option by its text; table cells keep its label. */
export function optionText(option: DataTableOption) {
  return nodeText(option.label) || option.value;
}

function textOf(node: ReactNode, fallback: string) {
  return typeof node === "string" || typeof node === "number"
    ? String(node)
    : fallback;
}

/** Applies defaults: `valueEnum` implies an enum column with a quick filter. */
export function normalizeColumns<TData>(
  columns: readonly DataTableColumn<TData>[],
  labels: DataTableLabels,
): NormalizedColumn<TData>[] {
  const locale = labels.locale;
  return columns.map((config) => {
    if (config.key === undefined) {
      const display = config as DataTableDisplayColumn<TData>;
      return {
        id: display.id,
        title: display.title ?? "",
        titleText: textOf(display.title, display.id),
        valueType: "text",
        display: true,
        config,
        sortable: false,
        keyword: false,
        filter: false,
        searchOnly: false,
        renderCell: display.render,
        getValue: () => undefined,
        exportText: () => "",
      } satisfies NormalizedColumn<TData>;
    }
    const column = config as DataTableDataColumn<TData>;
    const key = String(column.key);
    const id = column.id ?? key;
    const valueType: DataTableValueType =
      column.valueType ?? (column.valueEnum ? "enum" : "text");
    const context: FormatContext = {
      locale,
      labels,
      format: column.format,
      valueEnum: column.valueEnum,
    };
    const getValue = (row: TData) => getPath(row, key);
    const searchConfig =
      typeof column.search === "object" ? column.search : undefined;
    const search =
      column.search || column.searchOnly
        ? {
            ...searchConfig,
            type: searchConfig?.type ?? defaultSearchTypes[valueType],
            options: searchConfig?.options ?? column.valueEnum,
          }
        : undefined;
    const render = column.render as
      | ((value: unknown, row: TData, index: number) => ReactNode)
      | undefined;
    const exportValue = column.exportValue as
      | ((value: unknown, row: TData) => string)
      | undefined;
    function renderCell(row: TData, index: number): ReactNode {
      const value = getValue(row);
      if (render) return render(value, row, index);
      if (isEmptyValue(value))
        return <span className="text-muted-foreground">-</span>;
      if (valueType === "enum") return renderEnum(value, column.valueEnum);
      const text = formatValue(valueType, value, context);
      if (column.copyable) return <CopyText>{text}</CopyText>;
      if (column.ellipsis) return <LongText>{text}</LongText>;
      return text;
    }
    return {
      id,
      key,
      title: column.title ?? key,
      titleText: textOf(column.title, key),
      valueType,
      valueEnum: column.valueEnum,
      display: false,
      config,
      search,
      sortable: !!column.sortable || !!column.sorter,
      keyword: !!column.keyword,
      filter: column.filter ?? (valueType === "enum" && !!column.valueEnum),
      searchOnly: !!column.searchOnly,
      renderCell,
      getValue,
      exportText: (row) => {
        const value = getValue(row);
        if (exportValue) return exportValue(value, row);
        return formatValue(valueType, value, context);
      },
    } satisfies NormalizedColumn<TData>;
  });
}

/** A fixed-width column for plugin controls such as checkboxes and handles. */
export function utilityColumn<TData>(
  id: string,
  renderCell: (row: TData, index: number) => ReactNode,
  title: ReactNode = "",
): NormalizedColumn<TData> {
  return {
    id,
    title,
    titleText: "",
    valueType: "text",
    display: true,
    utility: true,
    config: { id, width: 40, render: () => null },
    sortable: false,
    keyword: false,
    filter: false,
    searchOnly: false,
    getValue: () => undefined,
    exportText: () => "",
    renderCell,
  };
}

"use client";

import { ScrollArea as ScrollAreaPrimitive } from "@base-ui/react/scroll-area";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Empty,
  EmptyContent,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { Skeleton } from "@/components/ui/skeleton";
import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "cn";
import { CircleAlert, Inbox, LoaderCircle } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type ComponentProps,
  type CSSProperties,
  Fragment,
  type PointerEvent,
  type ReactNode,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { DataTableColumnHeader } from "@/components/ui/data-table/column-header";
import { useDataTableContext } from "@/components/ui/data-table/context";
import type {
  DataTableDensity,
  DataTableInstance,
  NormalizedColumn,
} from "@/components/ui/data-table/types";

/** Beyond this many rows, layout animation costs more than it shows. */
const ANIMATED_ROW_LIMIT = 100;

const densityPadding: Record<DataTableDensity, string> = {
  compact: "py-1.5",
  default: "py-2.5",
  comfortable: "py-4",
};

const alignClass = {
  start: "text-start",
  center: "text-center",
  end: "text-end",
};

type Offsets = { start: Record<string, number>; end: Record<string, number> };

function pinSide(
  table: DataTableInstance<unknown>,
  column: NormalizedColumn<unknown>,
) {
  if (column.utility) return "start";
  return table.columnState.pinning[column.id];
}

/** Sticky offsets from measured header widths, so pinned columns stack. */
function usePinnedOffsets(
  table: DataTableInstance<unknown>,
  headers: React.RefObject<Map<string, HTMLTableCellElement>>,
) {
  const [offsets, setOffsets] = useState<Offsets>({ start: {}, end: {} });
  const columns = table.visibleColumns;
  useLayoutEffect(() => {
    const next: Offsets = { start: {}, end: {} };
    let start = 0;
    for (const column of columns) {
      if (pinSide(table, column) !== "start") continue;
      next.start[column.id] = start;
      start += headers.current.get(column.id)?.offsetWidth ?? 0;
    }
    let end = 0;
    for (const column of [...columns].reverse()) {
      if (pinSide(table, column) !== "end") continue;
      next.end[column.id] = end;
      end += headers.current.get(column.id)?.offsetWidth ?? 0;
    }
    setOffsets((current) =>
      JSON.stringify(current) === JSON.stringify(next) ? current : next,
    );
  });
  return offsets;
}

/**
 * Marks the scroller while content hides under pinned columns, so their
 * shadows only show when there is something to separate.
 */
function useScrollEdges(scroller: React.RefObject<HTMLDivElement | null>) {
  useLayoutEffect(() => {
    const element = scroller.current;
    if (!element) return;
    const update = () => {
      const offset = Math.abs(element.scrollLeft);
      const max = element.scrollWidth - element.clientWidth;
      element.toggleAttribute("data-scrolled-start", offset > 0);
      element.toggleAttribute("data-scrolled-end", offset < max - 1);
    };
    update();
    element.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(element);
    if (element.firstElementChild) observer.observe(element.firstElementChild);
    return () => {
      element.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [scroller]);
}

function cellLayout(
  table: DataTableInstance<unknown>,
  column: NormalizedColumn<unknown>,
  offsets: Offsets,
) {
  const side = pinSide(table, column);
  const width = table.columnState.widths[column.id] ?? column.config.width;
  const style: CSSProperties = {};
  if (width !== undefined) {
    style.width = width;
    style.minWidth = width;
    style.maxWidth = width;
  } else if (column.config.minWidth !== undefined) {
    style.minWidth = column.config.minWidth;
  }
  if (side === "start") style.insetInlineStart = offsets.start[column.id] ?? 0;
  if (side === "end") style.insetInlineEnd = offsets.end[column.id] ?? 0;
  const columns = table.visibleColumns;
  const lastStart = [...columns]
    .reverse()
    .find((entry) => pinSide(table, entry) === "start");
  const firstEnd = columns.find((entry) => pinSide(table, entry) === "end");
  return {
    style,
    pinned: !!side,
    className: cn(
      side && "sticky z-10",
      lastStart === column &&
        "after:pointer-events-none after:absolute after:inset-y-0 after:-end-3 after:w-3 after:bg-linear-to-r after:from-foreground/8 after:to-transparent after:opacity-0 after:transition-opacity group-data-[scrolled-start]/scroller:after:opacity-100 dark:after:from-black/50",
      firstEnd === column &&
        "before:pointer-events-none before:absolute before:inset-y-0 before:-start-3 before:w-3 before:bg-linear-to-l before:from-foreground/8 before:to-transparent before:opacity-0 before:transition-opacity group-data-[scrolled-end]/scroller:before:opacity-100 dark:before:from-black/50",
      column.config.align && alignClass[column.config.align],
      column.config.className,
    ),
  };
}

function ResizeHandle({
  table,
  column,
}: {
  table: DataTableInstance<unknown>;
  column: NormalizedColumn<unknown>;
}) {
  function start(event: PointerEvent<HTMLDivElement>) {
    event.preventDefault();
    const cell = event.currentTarget.parentElement;
    const startX = event.clientX;
    const startWidth = cell?.offsetWidth ?? 0;
    const direction = document.dir === "rtl" ? -1 : 1;
    const move = (moveEvent: globalThis.PointerEvent) => {
      const width = Math.max(
        48,
        Math.round(startWidth + (moveEvent.clientX - startX) * direction),
      );
      table.setColumnState((current) => ({
        ...current,
        widths: { ...current.widths, [column.id]: width },
      }));
    };
    const stop = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
  }
  return (
    <div
      aria-hidden
      title={table.labels.resizeColumn}
      onPointerDown={start}
      // Centred on the border with the next column; the last column has
      // none, so its handle stays inside the table rather than widening it
      // by a pixel and showing a horizontal scrollbar.
      className="absolute inset-y-2 -end-px w-1 cursor-col-resize touch-none rounded-full bg-border opacity-0 transition-opacity hover:opacity-100 group-hover/head:opacity-60 [th:last-child>&]:end-0"
    />
  );
}

function StatusRow({
  colSpan,
  children,
}: {
  colSpan: number;
  children: ReactNode;
}) {
  return (
    <tr>
      <td colSpan={colSpan} className="p-0">
        {children}
      </td>
    </tr>
  );
}

export function DataTableStatus({
  error,
  onRetry,
  title,
}: {
  error?: boolean;
  onRetry?: () => void;
  title: ReactNode;
}) {
  const table = useDataTableContext();
  return (
    <Empty role="status" className="min-h-48 border-0 py-10">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          {error ? <CircleAlert /> : <Inbox />}
        </EmptyMedia>
        <EmptyTitle>{title}</EmptyTitle>
      </EmptyHeader>
      {onRetry && (
        <EmptyContent>
          <Button variant="outline" size="sm" onClick={onRetry}>
            {table.labels.retry}
          </Button>
        </EmptyContent>
      )}
    </Empty>
  );
}

function useAnimatedRows(table: DataTableInstance<unknown>) {
  const reduced = useReducedMotion();
  return (
    !reduced &&
    !table.features.virtual &&
    !table.features.dragSort &&
    table.rows.length <= ANIMATED_ROW_LIMIT
  );
}

/** Virtual window over the rows from the scroll container's position. */
function useVirtualWindow(
  table: DataTableInstance<unknown>,
  scroller: React.RefObject<HTMLDivElement | null>,
) {
  const virtual = table.features.virtual;
  const [view, setView] = useState({ top: 0, height: 800 });
  useLayoutEffect(() => {
    const element = scroller.current;
    if (!virtual || !element) return;
    const update = () =>
      setView({ top: element.scrollTop, height: element.clientHeight || 800 });
    update();
    element.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => {
      element.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [virtual, scroller]);
  if (!virtual)
    return { start: 0, end: table.rows.length, before: 0, after: 0 };
  const { rowHeight, overscan } = virtual;
  const start = Math.max(0, Math.floor(view.top / rowHeight) - overscan);
  const end = Math.min(
    table.rows.length,
    Math.ceil((view.top + view.height) / rowHeight) + overscan,
  );
  return {
    start,
    end,
    before: start * rowHeight,
    after: (table.rows.length - end) * rowHeight,
  };
}

function DataRows({
  table,
  offsets,
  scroller,
}: {
  table: DataTableInstance<unknown>;
  offsets: Offsets;
  scroller: React.RefObject<HTMLDivElement | null>;
}) {
  const animated = useAnimatedRows(table);
  const range = useVirtualWindow(table, scroller);
  const columns = table.visibleColumns;
  const padding = densityPadding[table.density];
  const rowRenderer = table.plugins.find((plugin) => plugin.renderRow);
  const afterRenderers = table.plugins.filter(
    (plugin) => plugin.renderAfterRow,
  );
  const rows = table.rows.slice(range.start, range.end).map((row, offset) => {
    const index = range.start + offset;
    const id = table.getRowId(row, index);
    const selected = table.selection?.isSelected(id);
    const cells = columns.map((column) => {
      const layout = cellLayout(table, column, offsets);
      return (
        <td
          key={column.id}
          data-slot="data-table-cell"
          style={layout.style}
          className={cn(
            "whitespace-nowrap px-3 align-middle has-[[role=checkbox]]:pe-0",
            padding,
            layout.className,
            layout.pinned && "bg-inherit",
          )}
        >
          {column.renderCell(row, index)}
        </td>
      );
    });
    const rowProps = {
      "data-state": selected ? "selected" : undefined,
      className:
        "group/row border-b bg-background hover:bg-muted data-[state=selected]:bg-accent",
    } as ComponentProps<"tr">;
    const content = rowRenderer?.renderRow ? (
      rowRenderer.renderRow(
        { row, id, index, rowProps, children: cells },
        table,
      )
    ) : (
      <motion.tr
        key={id}
        {...(rowProps as object)}
        layout={animated ? "position" : false}
        initial={animated ? { opacity: 0, y: 6 } : false}
        animate={{ opacity: 1, y: 0 }}
        exit={
          animated ? { opacity: 0, transition: { duration: 0.12 } } : undefined
        }
        transition={{ type: "spring", stiffness: 500, damping: 40 }}
      >
        {cells}
      </motion.tr>
    );
    const after = afterRenderers.map((plugin) => (
      <AnimatePresence key={`${id}-${plugin.name}`} initial={false}>
        {plugin.renderAfterRow?.(row, id, table)}
      </AnimatePresence>
    ));
    if (after.length === 0 && !rowRenderer) return content;
    return (
      <Fragment key={id}>
        {content}
        {after}
      </Fragment>
    );
  });
  const spacer = (height: number, key: string) =>
    height > 0 && (
      <tr key={key} aria-hidden style={{ height }}>
        <td colSpan={columns.length} />
      </tr>
    );
  const body = (
    <>
      {spacer(range.before, "before")}
      {animated ? (
        <AnimatePresence initial={false} mode="popLayout">
          {rows}
        </AnimatePresence>
      ) : (
        rows
      )}
      {spacer(range.after, "after")}
    </>
  );
  return table.plugins.reduce<ReactNode>(
    (children, plugin) =>
      plugin.wrapBody ? plugin.wrapBody(children, table) : children,
    body,
  );
}

function SkeletonRows({ table }: { table: DataTableInstance<unknown> }) {
  const count = Math.min(table.state.pageSize, 8);
  return Array.from({ length: count }, (_, index) => (
    // biome-ignore lint/suspicious/noArrayIndexKey: placeholders have no identity.
    <tr key={index} className="border-b">
      {table.visibleColumns.map((column) => (
        <td
          key={column.id}
          className={cn("px-3", densityPadding[table.density])}
        >
          <Skeleton className="h-4 w-full max-w-40" />
        </td>
      ))}
    </tr>
  ));
}

function TableView({ className }: { className?: string }) {
  const table = useDataTableContext();
  const headers = useRef(new Map<string, HTMLTableCellElement>());
  const scroller = useRef<HTMLDivElement>(null);
  const offsets = usePinnedOffsets(table, headers);
  useScrollEdges(scroller);
  const columns = table.visibleColumns;
  const firstLoad = table.loading && table.rows.length === 0;
  let status: ReactNode = null;
  if (table.error)
    status = (
      <DataTableStatus
        error
        title={table.labels.loadFailed}
        onRetry={table.reload}
      />
    );
  else if (!table.loading && table.rows.length === 0)
    status = <DataTableStatus title={table.labels.noData} />;
  return (
    // Base UI draws the scrollbars, so every platform shows them the same
    // way: only while the pointer is over the table, it scrolls, or it has
    // keyboard focus.
    <ScrollAreaPrimitive.Root
      data-slot="data-table-scroll-area"
      className={cn(
        "group/scroll-area relative flex min-h-0 flex-col overflow-hidden",
        className,
      )}
    >
      <ScrollAreaPrimitive.Viewport
        ref={scroller}
        data-slot="data-table-scroller"
        className="group/scroller min-h-0 flex-1 overscroll-x-contain rounded-[inherit] outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
      >
        <table
          data-slot="data-table"
          aria-busy={table.loading}
          className="w-full caption-bottom border-separate border-spacing-0 text-sm [&_td]:border-b [&_tr:last-child_td]:border-b-0"
        >
          <thead className="sticky top-0 z-20 bg-background">
            <tr>
              {columns.map((column) => {
                const layout = cellLayout(table, column, offsets);
                const sorted = table.state.sort.find(
                  (item) => item.key === column.id,
                );
                let ariaSort: "ascending" | "descending" | "none" | undefined;
                if (column.sortable)
                  ariaSort = sorted
                    ? ({ asc: "ascending", desc: "descending" } as const)[
                        sorted.order
                      ]
                    : "none";
                return (
                  <th
                    key={column.id}
                    ref={(node) => {
                      if (node) headers.current.set(column.id, node);
                      else headers.current.delete(column.id);
                    }}
                    aria-sort={ariaSort}
                    style={layout.style}
                    className={cn(
                      // Positioned, so each resize handle sits on its own
                      // column's edge; pinned columns become sticky instead.
                      "group/head relative h-11 whitespace-nowrap border-b bg-background px-3 text-start align-middle font-medium text-muted-foreground has-[[role=checkbox]]:pe-0",
                      layout.className,
                      column.config.align && alignClass[column.config.align],
                    )}
                  >
                    {column.display ? (
                      column.title
                    ) : (
                      <DataTableColumnHeader
                        column={column}
                        className={cn(
                          column.config.align === "end" && "ms-auto",
                        )}
                      />
                    )}
                    {table.features.resizable && !column.utility && (
                      <ResizeHandle table={table} column={column} />
                    )}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody
            data-slot="data-table-body"
            className={cn(
              "transition-opacity",
              table.loading && !firstLoad && "pointer-events-none opacity-60",
            )}
          >
            {firstLoad && <SkeletonRows table={table} />}
            {!firstLoad && !status && (
              <DataRows table={table} offsets={offsets} scroller={scroller} />
            )}
            {status && <StatusRow colSpan={columns.length}>{status}</StatusRow>}
          </tbody>
        </table>
      </ScrollAreaPrimitive.Viewport>
      {table.loading && !firstLoad && (
        <div
          role="status"
          aria-label={table.labels.loading}
          className="pointer-events-none absolute inset-0 grid place-items-center"
        >
          <LoaderCircle className="size-5 animate-spin text-muted-foreground" />
        </div>
      )}
      <TableScrollbar orientation="horizontal" />
      <TableScrollbar orientation="vertical" />
      <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
  );
}

function TableScrollbar({
  orientation,
}: {
  orientation: "horizontal" | "vertical";
}) {
  return (
    // The vertical track starts below the sticky header (h-11), so the
    // header stays on top and the thumb only runs beside the rows. Base UI
    // sets `top` inline, hence the important modifier. Hidden until the
    // pointer enters the table, it scrolls (touch has no hover), or the
    // scroller has keyboard focus.
    <ScrollAreaPrimitive.Scrollbar
      orientation={orientation}
      className="z-30 flex touch-none select-none p-0.5 opacity-0 transition-opacity group-has-[[data-slot=data-table-scroller]:focus-visible]/scroll-area:opacity-70 data-[orientation=vertical]:top-11! data-[orientation=horizontal]:h-2.5 data-[orientation=vertical]:w-2.5 data-[orientation=horizontal]:flex-col data-hovering:opacity-70 data-scrolling:opacity-70 data-hovering:hover:opacity-100 motion-reduce:transition-none"
    >
      <ScrollAreaPrimitive.Thumb className="flex-1 rounded-full bg-muted-foreground/40 hover:bg-muted-foreground/60" />
    </ScrollAreaPrimitive.Scrollbar>
  );
}

/** Narrow screens show each row as a card of title and value pairs. */
function CardView({ className }: { className?: string }) {
  const table = useDataTableContext();
  const reduced = useReducedMotion();
  const columns = table.visibleColumns.filter((column) => !column.utility);
  const primary = columns.find((column) => column.config.primary) ?? columns[0];
  const rest = columns.filter((column) => column !== primary);
  let status: ReactNode = null;
  if (table.error)
    status = (
      <DataTableStatus
        error
        title={table.labels.loadFailed}
        onRetry={table.reload}
      />
    );
  else if (!table.loading && table.rows.length === 0)
    status = <DataTableStatus title={table.labels.noData} />;
  return (
    <div
      data-slot="data-table-cards"
      aria-busy={table.loading}
      className={cn("min-h-0 space-y-2 overflow-auto", className)}
    >
      {status}
      {table.loading &&
        table.rows.length === 0 &&
        Array.from({ length: 4 }, (_, index) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: placeholders have no identity.
          <Skeleton key={index} className="h-24 w-full rounded-xl" />
        ))}
      <AnimatePresence initial={false} mode="popLayout">
        {table.rows.map((row, index) => {
          const id = table.getRowId(row, index);
          const selected = table.selection?.isSelected(id) ?? false;
          return (
            <motion.div
              key={id}
              layout={reduced ? false : "position"}
              initial={reduced ? false : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduced ? undefined : { opacity: 0 }}
              data-state={selected ? "selected" : undefined}
              className="rounded-xl border bg-card p-3 text-sm data-[state=selected]:bg-accent"
            >
              <div className="mb-2 flex items-center gap-2 font-medium">
                {table.selection && (
                  <Checkbox
                    aria-label={table.labels.selectRow}
                    checked={selected}
                    disabled={table.selection.isDisabled(row)}
                    onCheckedChange={() => table.selection?.toggle(id, row)}
                  />
                )}
                <div className="min-w-0 flex-1 truncate">
                  {primary?.renderCell(row, index)}
                </div>
              </div>
              <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1.5">
                {rest.map((column) => (
                  <div key={column.id} className="contents">
                    <dt className="text-muted-foreground">{column.title}</dt>
                    <dd className="min-w-0 text-end">
                      {column.renderCell(row, index)}
                    </dd>
                  </div>
                ))}
              </dl>
              {table.plugins.map(
                (plugin) =>
                  plugin.renderAfterRow && (
                    <table key={plugin.name} className="mt-2 w-full">
                      <tbody>
                        <AnimatePresence initial={false}>
                          {plugin.renderAfterRow(row, id, table)}
                        </AnimatePresence>
                      </tbody>
                    </table>
                  ),
              )}
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

export interface DataTableContentProps {
  readonly className?: string;
  /** Shows cards on narrow screens; defaults to true. */
  readonly responsive?: boolean;
}

/** The rows of the table: header, body, loading, empty and error states. */
export function DataTableContent({
  className,
  responsive = true,
}: DataTableContentProps) {
  const mobile = useIsMobile();
  const table = useDataTableContext();
  // A list or card view from the views plugin, when the reader picked one
  if (table.view !== "table")
    for (const plugin of table.plugins) {
      const view = plugin.renderView?.(table.view, table);
      // The view draws its own surface, so only the layout classes carry over
      if (view !== undefined)
        return (
          <div
            data-slot="data-table-view"
            className={cn(
              "flex min-h-0 flex-col",
              className,
              "rounded-none border-0",
            )}
          >
            {view}
          </div>
        );
    }
  if (responsive && mobile) return <CardView className={className} />;
  return <TableView className={className} />;
}

"use client";

import { createContext, type ReactNode, useContext } from "react";
import type { DataTableInstance, DataTablePlugin } from "@/components/ui/data-table/types";

const DataTableContext = createContext<DataTableInstance<unknown> | null>(null);

export function DataTableProvider<TData>({
  table,
  children,
}: {
  table: DataTableInstance<TData>;
  children: ReactNode;
}) {
  return (
    <DataTableContext.Provider value={table as DataTableInstance<unknown>}>
      {table.plugins.map(
        (plugin) =>
          plugin.setup && (
            <PluginSetup key={plugin.name} plugin={plugin} table={table} />
          ),
      )}
      {children}
    </DataTableContext.Provider>
  );
}

/** Each plugin's hooks live in their own component, so plugins can change. */
function PluginSetup<TData>({
  plugin,
  table,
}: {
  plugin: DataTablePlugin<TData>;
  table: DataTableInstance<TData>;
}) {
  plugin.setup?.(table);
  return null;
}

/** The table from the nearest DataTable or DataTableProvider. */
export function useDataTableContext<TData = unknown>() {
  const table = useContext(DataTableContext);
  if (!table) throw new Error("DataTable parts must render inside DataTable");
  return table as DataTableInstance<TData>;
}

"use client";

import { cn } from "cn";
import { type ReactNode, type Ref, useImperativeHandle } from "react";
import { DataTableContent } from "@/components/ui/data-table/content";
import { DataTableProvider } from "@/components/ui/data-table/context";
import { DataTablePagination } from "@/components/ui/data-table/pagination";
import { DataTableSlotContent, DataTableToolbar } from "@/components/ui/data-table/toolbar";
import type { DataTableActions, DataTableInstance } from "@/components/ui/data-table/types";
import { type UseDataTableOptions, useDataTable } from "@/components/ui/data-table/use-data-table";

interface DataTableFrameProps {
  /** Shown at the start of the toolbar. */
  readonly title?: ReactNode;
  /** Buttons at the end of the toolbar, before plugin controls. */
  readonly toolbar?: ReactNode;
  /**
   * Lists active conditions as removable chips below the toolbar. Off by
   * default: each control shows and clears its own value, and the toolbar
   * offers one clear-all button while any condition applies.
   */
  readonly chips?: boolean;
  /**
   * Filters that sit on the toolbar row; past this the first stays and the
   * rest share one Filters button. Defaults to 2.
   */
  readonly maxFilters?: number;
  /**
   * `fill` takes the parent's height: the table is as tall as its rows up to
   * the space left, then scrolls, and the pagination stays at the bottom.
   * `auto` grows with its rows.
   */
  readonly layout?: "fill" | "auto";
  /** Shows rows as cards on narrow screens; defaults to true. */
  readonly responsive?: boolean;
  readonly className?: string;
  readonly actionRef?: Ref<DataTableActions>;
  /** Replaces the default layout; compose DataTable parts inside. */
  readonly children?: ReactNode;
}

export type DataTableProps<TData> = DataTableFrameProps &
  (
    | (UseDataTableOptions<TData> & { readonly table?: undefined })
    | {
        /** A table from `useDataTable`, for state you read outside. */
        readonly table: DataTableInstance<TData>;
      }
  );

function DataTableFrame<TData>({
  table,
  title,
  toolbar,
  chips,
  maxFilters,
  layout = "fill",
  responsive = true,
  className,
  actionRef,
  children,
}: DataTableFrameProps & { table: DataTableInstance<TData> }) {
  useImperativeHandle(
    actionRef,
    () => ({ reload: table.reload, reset: table.reset }),
    [table.reload, table.reset],
  );
  const fill = layout === "fill";
  return (
    <DataTableProvider table={table}>
      <div
        data-slot="data-table-root"
        data-layout={layout}
        className={cn(
          "relative flex min-w-0 flex-col gap-3",
          fill && "h-full min-h-0",
          className,
        )}
      >
        {children ?? (
          <>
            <DataTableSlotContent slot="header" />
            <DataTableToolbar
              title={title}
              actions={toolbar}
              chips={chips}
              maxFilters={maxFilters}
            />
            {/* A few rows keep their own height; the space goes between the
                table and the pagination rather than into an empty table. */}
            <DataTableContent
              responsive={responsive}
              className={cn("rounded-xl border", fill && "flex-initial")}
            />
            {table.paginated && (
              <DataTablePagination className={cn(fill && "mt-auto")} />
            )}
          </>
        )}
        <div
          className={cn(
            "pointer-events-none absolute inset-x-0 z-30 flex justify-center",
            table.paginated ? "bottom-14" : "bottom-4",
          )}
        >
          <DataTableSlotContent slot="floating" />
        </div>
      </div>
    </DataTableProvider>
  );
}

function DataTableWithState<TData>({
  title,
  toolbar,
  chips,
  maxFilters,
  layout,
  responsive,
  className,
  actionRef,
  children,
  ...options
}: DataTableFrameProps & UseDataTableOptions<TData>) {
  const table = useDataTable(options);
  return (
    <DataTableFrame
      table={table}
      title={title}
      toolbar={toolbar}
      chips={chips}
      maxFilters={maxFilters}
      layout={layout}
      responsive={responsive}
      className={className}
      actionRef={actionRef}
    >
      {children}
    </DataTableFrame>
  );
}

/**
 * A data table driven by field configuration: pass `columns` with `data` or
 * `request`, and add features with `plugins`.
 */
export function DataTable<TData>(props: DataTableProps<TData>) {
  if (props.table) return <DataTableFrame {...props} table={props.table} />;
  return <DataTableWithState {...props} />;
}

"use client";

import {
  DatePicker,
  type DatePickerPreset,
} from "@/components/ui/date-picker";
import { formatLocalDate, parseLocalDate } from "@/lib/date-time";
import { useMemo } from "react";
import { useDataTableContext } from "@/components/ui/data-table/context";

interface DateFieldProps {
  readonly value: unknown;
  readonly onChange: (value: unknown) => void;
  /** Adds a time of day; values become `yyyy-mm-ddThh:mm`. */
  readonly time?: boolean;
  readonly id?: string;
  readonly label?: string;
  readonly labelledBy?: string;
  readonly className?: string;
  /** Quick ranges shown beside the calendar (range fields only). */
  readonly presets?: readonly DatePickerPreset[];
}

/**
 * A table's date filter. It reads any value the engine matches (a Date, a
 * timestamp or a date string) and writes local `yyyy-mm-dd` strings, as the
 * native inputs did, so filtering and URL state are unchanged.
 */
export function DataTableDateField({
  value,
  onChange,
  time = false,
  id,
  label,
  labelledBy,
  className,
}: DateFieldProps) {
  const table = useDataTableContext();
  return (
    <DatePicker
      id={id}
      className={className}
      showTime={time}
      locale={table.labels.locale}
      aria-label={label}
      aria-labelledby={labelledBy}
      value={parseLocalDate(value)}
      onValueChange={(next) =>
        onChange(next ? formatLocalDate(next, time && {}) : undefined)
      }
    />
  );
}

/** A `[start, end]` table filter; either end may be empty. */
export function DataTableDateRangeField({
  value,
  onChange,
  time = false,
  id,
  label,
  labelledBy,
  className,
  presets,
}: DateFieldProps) {
  const table = useDataTableContext();
  const { rangeStart, rangeEnd, locale } = table.labels;
  const labels = useMemo(
    () => ({ start: rangeStart, end: rangeEnd }),
    [rangeStart, rangeEnd],
  );
  const [start, end] = Array.isArray(value) ? value : [];
  const from = parseLocalDate(start);
  const to = parseLocalDate(end);
  return (
    <DatePicker
      mode="range"
      id={id}
      className={className}
      showTime={time}
      locale={locale}
      labels={labels}
      aria-label={label}
      aria-labelledby={labelledBy}
      value={from || to ? { from, to } : undefined}
      presets={presets}
      onValueChange={(next) => {
        const pair = [next?.from, next?.to].map((date) =>
          date ? formatLocalDate(date, time && {}) : undefined,
        );
        onChange(pair.every((item) => item === undefined) ? undefined : pair);
      }}
    />
  );
}

import type {
  DataTableQuery,
  DataTableSearchType,
  FilterGroup,
  FilterOperator,
  FilterRule,
  NormalizedColumn,
  SortItem,
} from "@/components/ui/data-table/types";

/** Reads a dot path such as `profile.city`. */
export function getPath(row: unknown, path: string): unknown {
  let value = row;
  for (const part of path.split(".")) {
    if (value === null || value === undefined) return undefined;
    value = (value as Record<string, unknown>)[part];
  }
  return value;
}

export function isEmptyValue(value: unknown): boolean {
  if (value === undefined || value === null || value === "") return true;
  if (Array.isArray(value)) return value.every(isEmptyValue);
  return false;
}

export function toTime(value: unknown): number | undefined {
  if (value instanceof Date) return value.getTime();
  if (typeof value === "number") return value;
  if (typeof value !== "string" || value === "") return undefined;
  // Date-only strings parse as UTC midnight; read them as local days instead.
  const day = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (day) return new Date(+day[1], +day[2] - 1, +day[3]).getTime();
  const time = Date.parse(value);
  return Number.isNaN(time) ? undefined : time;
}

function toNumber(value: unknown): number | undefined {
  if (value === "" || value === null || value === undefined) return undefined;
  const number = Number(value);
  return Number.isNaN(number) ? undefined : number;
}

function includesText(cell: unknown, value: unknown) {
  return String(cell ?? "")
    .toLocaleLowerCase()
    .includes(String(value).toLocaleLowerCase());
}

/** A date input value covers its whole day; a datetime value is exact. */
function rangeEnd(value: unknown, wholeDay: boolean) {
  const time = toTime(value);
  if (time === undefined || !wholeDay) return time;
  return time + 24 * 60 * 60 * 1000 - 1;
}

function inRange(
  cell: number | undefined,
  start: number | undefined,
  end: number | undefined,
) {
  if (cell === undefined) return false;
  if (start !== undefined && cell < start) return false;
  if (end !== undefined && cell > end) return false;
  return true;
}

function asRange(value: unknown): readonly unknown[] {
  return Array.isArray(value) ? value : [];
}

const searchMatchers: Record<
  DataTableSearchType,
  (cell: unknown, value: unknown) => boolean
> = {
  text: includesText,
  number: (cell, value) => toNumber(cell) === toNumber(value),
  numberRange: (cell, value) => {
    const [start, end] = asRange(value);
    return inRange(toNumber(cell), toNumber(start), toNumber(end));
  },
  select: (cell, value) => String(cell) === String(value),
  multiSelect: (cell, value) =>
    asRange(value).some((item) => String(item) === String(cell)),
  date: (cell, value) =>
    inRange(toTime(cell), toTime(value), rangeEnd(value, true)),
  dateRange: (cell, value) => {
    const [start, end] = asRange(value);
    return inRange(toTime(cell), toTime(start), rangeEnd(end, true));
  },
  datetimeRange: (cell, value) => {
    const [start, end] = asRange(value);
    return inRange(toTime(cell), toTime(start), rangeEnd(end, false));
  },
  boolean: (cell, value) => String(Boolean(cell)) === String(value),
  custom: (cell, value) => String(cell) === String(value),
};

export function matchesSearch(
  type: DataTableSearchType,
  cell: unknown,
  value: unknown,
) {
  return searchMatchers[type](cell, value);
}

function compareValues(a: unknown, b: unknown) {
  const left = toNumber(a) ?? toTime(a);
  const right = toNumber(b) ?? toTime(b);
  if (left !== undefined && right !== undefined) return left - right;
  return String(a ?? "").localeCompare(String(b ?? ""));
}

const ruleMatchers: Record<
  FilterRule["operator"],
  (cell: unknown, value: unknown) => boolean
> = {
  eq: (cell, value) => compareValues(cell, value) === 0,
  neq: (cell, value) => compareValues(cell, value) !== 0,
  contains: includesText,
  startsWith: (cell, value) =>
    String(cell ?? "")
      .toLocaleLowerCase()
      .startsWith(String(value).toLocaleLowerCase()),
  gt: (cell, value) => compareValues(cell, value) > 0,
  gte: (cell, value) => compareValues(cell, value) >= 0,
  lt: (cell, value) => compareValues(cell, value) < 0,
  lte: (cell, value) => compareValues(cell, value) <= 0,
  between: (cell, value) => {
    const [start, end] = asRange(value);
    const afterStart = isEmptyValue(start) || compareValues(cell, start) >= 0;
    const beforeEnd = isEmptyValue(end) || compareValues(cell, end) <= 0;
    return afterStart && beforeEnd;
  },
  in: (cell, value) =>
    asRange(value).some((item) => String(item) === String(cell)),
  notIn: (cell, value) =>
    !asRange(value).some((item) => String(item) === String(cell)),
  isEmpty: (cell) => isEmptyValue(cell),
};

export function isFilterOperator(value: unknown): value is FilterOperator {
  return typeof value === "string" && Object.hasOwn(ruleMatchers, value);
}

export function matchesRule(rule: FilterRule, cell: unknown) {
  if (rule.operator !== "isEmpty" && isEmptyValue(rule.value)) return true;
  return ruleMatchers[rule.operator](cell, rule.value);
}

function matchesGroup<TData>(
  row: TData,
  group: FilterGroup,
  columns: ReadonlyMap<string, NormalizedColumn<TData>>,
) {
  const results = group.rules.map((rule) => {
    const column = columns.get(rule.field);
    return column ? matchesRule(rule, column.getValue(row)) : true;
  });
  if (results.length === 0) return true;
  return group.logic === "or" ? results.some(Boolean) : results.every(Boolean);
}

/** Applies keyword, query form, quick filters and advanced rules with AND. */
export function filterRows<TData>(
  rows: readonly TData[],
  columns: readonly NormalizedColumn<TData>[],
  query: DataTableQuery,
): TData[] {
  const byId = new Map(columns.map((column) => [column.id, column]));
  const keyword = query.keyword.trim();
  const keywordColumns = columns.filter((column) => column.keyword);
  const searches = Object.entries(query.search).flatMap(([id, value]) => {
    const column = byId.get(id);
    if (!column?.search || isEmptyValue(value)) return [];
    return [{ column, value, search: column.search }];
  });
  const filters = Object.entries(query.filters).flatMap(([id, values]) => {
    const column = byId.get(id);
    return column && values.length > 0 ? [{ column, values }] : [];
  });
  return rows.filter((row) => {
    if (
      keyword &&
      !keywordColumns.some((column) =>
        includesText(column.getValue(row), keyword),
      )
    )
      return false;
    for (const { column, value, search } of searches) {
      const cell = column.getValue(row);
      const matched = search.match
        ? search.match(cell, value)
        : matchesSearch(search.type, cell, value);
      if (!matched) return false;
    }
    for (const { column, values } of filters) {
      if (!values.includes(String(column.getValue(row)))) return false;
    }
    return query.advanced ? matchesGroup(row, query.advanced, byId) : true;
  });
}

export function sortRows<TData>(
  rows: readonly TData[],
  columns: readonly NormalizedColumn<TData>[],
  sort: readonly SortItem[],
): TData[] {
  const sorters = sort.flatMap((item) => {
    const column = columns.find((entry) => entry.id === item.key);
    if (!column) return [];
    const direction = item.order === "asc" ? 1 : -1;
    const config = column.config as { sorter?: (a: TData, b: TData) => number };
    const compare =
      config.sorter ??
      ((a: TData, b: TData) =>
        compareValues(column.getValue(a), column.getValue(b)));
    return [(a: TData, b: TData) => compare(a, b) * direction];
  });
  if (sorters.length === 0) return [...rows];
  return rows
    .map((row, index) => ({ row, index }))
    .sort((a, b) => {
      for (const sorter of sorters) {
        const result = sorter(a.row, b.row);
        if (result !== 0) return result;
      }
      return a.index - b.index;
    })
    .map((entry) => entry.row);
}

export function countFacets<TData>(
  rows: readonly TData[],
  column: NormalizedColumn<TData>,
) {
  const counts = new Map<string, number>();
  for (const row of rows) {
    const value = String(column.getValue(row));
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }
  return counts;
}

/** Query form values as request parameters, after each field's transform. */
export function requestSearch<TData>(
  columns: readonly NormalizedColumn<TData>[],
  search: Readonly<Record<string, unknown>>,
) {
  const result: Record<string, unknown> = {};
  for (const [id, value] of Object.entries(search)) {
    if (isEmptyValue(value)) continue;
    const transform = columns.find((column) => column.id === id)?.search
      ?.transform;
    if (transform) Object.assign(result, transform(value));
    else result[id] = value;
  }
  return result;
}

// Spreadsheets run a cell that starts with =, +, @, a tab or a return as a
// formula, and one that starts with - when an operator follows; plain
// negative numbers stay numbers.
const formulaStart = /^[=+@\t\r]|^-.*[=+*/^&|!@(]/;

function csvCell(value: string) {
  const safe = formulaStart.test(value) ? `'${value}` : value;
  return /[",\n\r]/.test(safe) ? `"${safe.replaceAll('"', '""')}"` : safe;
}

/** CSV with a byte order mark so spreadsheet apps read UTF-8. */
export function toCsv<TData>(
  rows: readonly TData[],
  columns: readonly NormalizedColumn<TData>[],
) {
  const dataColumns = columns.filter((column) => !column.display);
  const lines = [
    dataColumns.map((column) => csvCell(column.titleText)).join(","),
    ...rows.map((row) =>
      dataColumns.map((column) => csvCell(column.exportText(row))).join(","),
    ),
  ];
  return `﻿${lines.join("\r\n")}`;
}

export function downloadText(text: string, filename: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  // Revoking right away can cancel the download in Firefox and Safari.
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

