type TableActions<TData> = Pick<
  DataTableInstance<TData>,
  | "setKeyword"
  | "setSearch"
  | "setFilter"
  | "setAdvanced"
  | "resetQuery"
  | "toggleSort"
  | "setSort"
  | "setPage"
  | "setPageSize"
  | "resetColumns"
  | "toggleExpanded"
  | "setRows"
  | "reload"
  | "reset"
>;

const defaultPageSizes = [10, 20, 50, 100];
const emptyRows: readonly never[] = [];
const noSubscription = () => () => {};

function initialSearch<TData>(columns: readonly NormalizedColumn<TData>[]) {
  const search: Record<string, unknown> = {};
  for (const column of columns) {
    if (column.search?.initialValue !== undefined)
      search[column.id] = column.search.initialValue;
  }
  return search;
}

function initialColumnState<TData>(
  columns: readonly NormalizedColumn<TData>[],
): DataTableColumnState {
  const visibility: Record<string, boolean> = {};
  const pinning: Record<string, "start" | "end" | undefined> = {};
  for (const column of columns) {
    if (column.config.hidden) visibility[column.id] = false;
    if (column.config.fixed) pinning[column.id] = column.config.fixed;
  }
  return { visibility, order: [], pinning, widths: {} };
}

/** Utility columns stay at the start; pinned columns move to the edges. */
export function orderColumns<TData>(
  columns: readonly NormalizedColumn<TData>[],
  state: DataTableColumnState,
) {
  const rank = new Map(state.order.map((id, index) => [id, index]));
  const data = columns
    .filter(
      (column) =>
        !column.utility &&
        !column.searchOnly &&
        state.visibility[column.id] !== false,
    )
    .map((column, index) => ({ column, index }))
    .sort(
      (a, b) =>
        (rank.get(a.column.id) ?? state.order.length + a.index) -
        (rank.get(b.column.id) ?? state.order.length + b.index),
    )
    .map((entry) => entry.column);
  const pinned = (side: "start" | "end") =>
    data.filter((column) => state.pinning[column.id] === side);
  const free = data.filter((column) => !state.pinning[column.id]);
  return [
    ...columns.filter((column) => column.utility),
    ...pinned("start"),
    ...free,
    ...pinned("end"),
  ];
}

/** State plugins restore, such as the address bar or saved columns. */
function restoredState<TData>(plugins: readonly DataTablePlugin<TData>[]) {
  return {
    state: Object.assign(
      {},
      ...plugins.map((plugin) => plugin.initialState?.()),
    ) as Partial<DataTableState>,
    columns: Object.assign(
      {},
      ...plugins.map((plugin) => plugin.initialColumnState?.()),
    ) as Partial<DataTableColumnState>,
    density: plugins.map((plugin) => plugin.initialDensity?.()).find(Boolean),
    view: plugins.map((plugin) => plugin.initialView?.()).find(Boolean),
  };
}

function createState<TData>(
  initial: UseDataTableOptions<TData>["initialState"],
  columns: readonly NormalizedColumn<TData>[],
  defaultPageSize: number,
  restored: Partial<DataTableState> = {},
): DataTableState {
  return {
    sort: restored.sort ?? initial?.sort ?? [],
    page: restored.page ?? initial?.page ?? 1,
    pageSize: restored.pageSize ?? defaultPageSize,
    query: {
      keyword: "",
      filters: {},
      ...initial?.query,
      search: { ...initialSearch(columns), ...initial?.query?.search },
      ...restored.query,
    },
  };
}

/**
 * Puts reordered rows back into the slots they held, so rows a filter hides
 * keep their place. Rows that are not all from `all` replace them instead.
 */
function mergeRows<TData>(all: readonly TData[], next: readonly TData[]) {
  const moved = new Set(next);
  const slots = all.filter((row) => moved.has(row)).length;
  if (slots !== next.length) return next;
  let cursor = 0;
  return all.map((row) => (moved.has(row) ? next[cursor++] : row));
}

function selectionColumn<TData>(
  labels: DataTableLabels,
  getSelection: () => DataTableSelection<TData> | undefined,
  getRowId: (row: TData, index: number) => string,
  isDisabled?: (row: TData) => boolean,
): NormalizedColumn<TData> {
  return utilityColumn(
    "__select",
    (row, index) => {
      const selection = getSelection();
      const id = getRowId(row, index);
      return (
        <Checkbox
          aria-label={labels.selectRow}
          checked={selection?.isSelected(id) ?? false}
          disabled={isDisabled?.(row)}
          onCheckedChange={() => selection?.toggle(id, row)}
          onClick={(event) => event.stopPropagation()}
        />
      );
    },
    <SelectAllCheckbox />,
  );
}

/** Reads the live table from context: the header element itself is memoized. */
function SelectAllCheckbox() {
  const { selection, labels } = useDataTableContext();
  return (
    <Checkbox
      aria-label={labels.selectAll}
      checked={selection?.pageState === "all"}
      indeterminate={selection?.pageState === "some"}
      onCheckedChange={() => selection?.togglePage()}
    />
  );
}

/** State, data pipeline and plugin host for a data table. */
export function useDataTable<TData>(
  options: UseDataTableOptions<TData>,
): DataTableInstance<TData> {
  const {
    columns: columnConfigs,
    data,
    request,
    rowKey,
    plugins = emptyRows as readonly DataTablePlugin<TData>[],
    rowSelection,
    pagination,
    onStateChange,
    defaultDensity = "default",
  } = options;
  const labels = useMemo(
    () => resolveDataTableLabels(options.labels),
    [options.labels],
  );
  const remote = !!request;
  const paginated = pagination !== false;
  const pageSizes = (pagination || undefined)?.pageSizes ?? defaultPageSizes;
  const defaultPageSize =
    options.initialState?.pageSize ??
    (pagination ? pagination.pageSize : undefined) ??
    pageSizes[0];
  const features = useMemo<DataTableFeatures>(
    () => Object.assign({}, ...plugins.map((plugin) => plugin.features)),
    [plugins],
  );

  // Without a rowKey, each row object keeps one id across pages, sorting and
  // filtering, so selection and expansion never move to another row.
  const autoIds = useRef({ ids: new WeakMap<object, string>(), next: 0 });
  const getRowId = useCallback(
    (row: TData, index: number) => {
      if (typeof rowKey === "function") return rowKey(row, index);
      if (rowKey !== undefined) return String(row[rowKey]);
      if (typeof row !== "object" || row === null) return String(index);
      const { ids } = autoIds.current;
      let id = ids.get(row);
      if (id === undefined) {
        id = String(autoIds.current.next++);
        ids.set(row, id);
      }
      return id;
    },
    [rowKey],
  );

  const baseColumns = useMemo(
    () => normalizeColumns(columnConfigs, labels),
    [columnConfigs, labels],
  );

  // Plugins restore from the address bar and storage, which the server cannot
  // read. Server and hydration renders use the defaults, and the restored
  // state lands in a layout effect before the first paint.
  const hydrating = useSyncExternalStore(
    noSubscription,
    () => false,
    () => true,
  );
  const restoreAfterHydration = useRef(hydrating);
  const [restored] = useState(() =>
    hydrating ? undefined : restoredState(plugins),
  );
  const [state, setStateValue] = useState<DataTableState>(() =>
    createState(
      options.initialState,
      baseColumns,
      defaultPageSize,
      restored?.state,
    ),
  );
  const initialStateRef = useRef(state);
  const setState = useCallback(
    (updater: (current: DataTableState) => DataTableState) =>
      setStateValue(updater),
    [],
  );

  const defaultColumnState = useMemo(
    () => initialColumnState(baseColumns),
    [baseColumns],
  );
  const [columnState, setColumnStateValue] = useState<DataTableColumnState>(
    () => ({ ...defaultColumnState, ...restored?.columns }),
  );
  const [density, setDensity] = useState<DataTableDensity>(
    () => restored?.density ?? defaultDensity,
  );
  const [view, setView] = useState<DataTableView>(
    () =>
      restored?.view ??
      plugins.map((plugin) => plugin.defaultView).find(Boolean) ??
      "table",
  );

  // biome-ignore lint/correctness/useExhaustiveDependencies: restores once, from the options of the hydrating render.
  useLayoutEffect(() => {
    if (!restoreAfterHydration.current) return;
    restoreAfterHydration.current = false;
    const late = restoredState(plugins);
    if (Object.keys(late.state).length > 0) {
      const next = createState(
        options.initialState,
        baseColumns,
        defaultPageSize,
        late.state,
      );
      initialStateRef.current = next;
      setStateValue(next);
    }
    if (Object.keys(late.columns).length > 0)
      setColumnStateValue((current) => ({ ...current, ...late.columns }));
    if (late.density) setDensity(late.density);
    if (late.view) setView(late.view);
  }, []);

  // Drag sorting replaces local rows until the data prop changes.
  const [localOverride, setLocalOverride] = useState<{
    source: readonly TData[] | undefined;
    rows: readonly TData[];
  }>();
  const localData =
    localOverride && localOverride.source === data
      ? localOverride.rows
      : (data ?? emptyRows);

  const [remoteResult, setRemoteResult] = useState<{
    rows: readonly TData[];
    total: number | undefined;
  }>({ rows: emptyRows, total: undefined });
  const [loadingRequest, setLoadingRequest] = useState(remote);
  const [error, setError] = useState<unknown>();
  const [reloadToken, setReloadToken] = useState(0);
  const [selected, setSelected] = useState<ReadonlyMap<string, TData>>(
    () => new Map(),
  );
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(
    () => new Set(),
  );

  const selectionOptions =
    typeof rowSelection === "object" ? rowSelection : undefined;
  const selectionRef = useRef<DataTableSelection<TData> | undefined>(undefined);
  const columns = useMemo(() => {
    let result: NormalizedColumn<TData>[] = [...baseColumns];
    if (rowSelection)
      result = [
        selectionColumn(
          labels,
          () => selectionRef.current,
          getRowId,
          selectionOptions?.isDisabled,
        ),
        ...result,
      ];
    for (const plugin of plugins)
      if (plugin.columns) result = plugin.columns(result);
    return result;
  }, [
    baseColumns,
    rowSelection,
    labels,
    getRowId,
    selectionOptions?.isDisabled,
    plugins,
  ]);

  const filtered = useMemo(
    () => (remote ? emptyRows : filterRows(localData, columns, state.query)),
    [remote, localData, columns, state.query],
  );
  const sorted = useMemo(
    () => (remote ? emptyRows : sortRows(filtered, columns, state.sort)),
    [remote, filtered, columns, state.sort],
  );

  const requestRef = useRef(request);
  requestRef.current = request;
  const requestParams = useMemo(
    () => ({
      page: state.page,
      pageSize: state.pageSize,
      sort: state.sort,
      keyword: state.query.keyword,
      filters: state.query.filters,
      advanced: state.query.advanced,
      search: requestSearch(columns, state.query.search),
    }),
    [state, columns],
  );
  const requestKey = JSON.stringify(requestParams);

  // biome-ignore lint/correctness/useExhaustiveDependencies: requestKey captures every parameter; reloadToken forces a refetch.
  useEffect(() => {
    if (!remote) return;
    const controller = new AbortController();
    setLoadingRequest(true);
    setError(undefined);
    Promise.resolve()
      // A request superseded in the same task, such as by restored URL
      // state after hydration, is never sent.
      .then(() =>
        controller.signal.aborted
          ? undefined
          : requestRef.current?.({
              ...requestParams,
              signal: controller.signal,
            }),
      )
      .then(
        (response) => {
          if (controller.signal.aborted || !response) return;
          setRemoteResult({ rows: response.data, total: response.total });
          setLoadingRequest(false);
        },
        (reason: unknown) => {
          if (controller.signal.aborted) return;
          setError(reason);
          setLoadingRequest(false);
        },
      );
    return () => controller.abort();
  }, [remote, requestKey, reloadToken]);

  const total = remote ? remoteResult.total : sorted.length;
  const rows = useMemo(() => {
    if (remote) return remoteResult.rows;
    if (!paginated || features.dragSort) return sorted;
    const start = (state.page - 1) * state.pageSize;
    return sorted.slice(start, start + state.pageSize);
  }, [
    remote,
    remoteResult.rows,
    paginated,
    features.dragSort,
    sorted,
    state.page,
    state.pageSize,
  ]);
  const pageCount =
    total === undefined
      ? undefined
      : Math.max(1, Math.ceil(total / state.pageSize));
  const hasNextPage =
    pageCount === undefined
      ? rows.length >= state.pageSize
      : state.page < pageCount;

  // Keep the page in range after filtering or deleting rows.
  useEffect(() => {
    if (pageCount !== undefined && state.page > pageCount)
      setStateValue((current) => ({ ...current, page: pageCount }));
  }, [pageCount, state.page]);

  const onStateChangeRef = useRef(onStateChange);
  onStateChangeRef.current = onStateChange;
  const reportedState = useRef(state);
  useEffect(() => {
    if (reportedState.current === state) return;
    reportedState.current = state;
    onStateChangeRef.current?.(state);
  }, [state]);

  // Reported after commit: the updater stays pure, and a parent may set its
  // own state in onChange.
  const onSelectionChangeRef = useRef(selectionOptions?.onChange);
  onSelectionChangeRef.current = selectionOptions?.onChange;
  const reportedSelection = useRef(selected);
  useEffect(() => {
    if (reportedSelection.current === selected) return;
    reportedSelection.current = selected;
    onSelectionChangeRef.current?.([...selected.values()]);
  }, [selected]);
  const updateSelected = useCallback(
    (update: (current: Map<string, TData>) => void) =>
      setSelected((current) => {
        const next = new Map(current);
        update(next);
        return next;
      }),
    [],
  );

  const selection = useMemo<DataTableSelection<TData> | undefined>(() => {
    if (!rowSelection) return undefined;
    const isDisabled = (row: TData) => !!selectionOptions?.isDisabled?.(row);
    const pageIds = rows.flatMap((row, index) =>
      isDisabled(row) ? [] : [[getRowId(row, index), row] as const],
    );
    const selectedOnPage = pageIds.filter(([id]) => selected.has(id)).length;
    let pageState: DataTableSelection<TData>["pageState"] = "none";
    if (selectedOnPage > 0)
      pageState = selectedOnPage === pageIds.length ? "all" : "some";
    return {
      ids: new Set(selected.keys()),
      rows: [...selected.values()],
      pageState,
      isSelected: (id) => selected.has(id),
      isDisabled,
      toggle: (id, row) => {
        if (isDisabled(row)) return;
        updateSelected((next) => {
          if (next.has(id)) next.delete(id);
          else next.set(id, row);
        });
      },
      togglePage: () =>
        updateSelected((next) => {
          for (const [id, row] of pageIds) {
            if (pageState === "all") next.delete(id);
            else next.set(id, row);
          }
        }),
      clear: () => updateSelected((next) => next.clear()),
    };
  }, [
    rowSelection,
    selectionOptions?.isDisabled,
    rows,
    getRowId,
    selected,
    updateSelected,
  ]);
  selectionRef.current = selection;

  const toFirstPage = useCallback(
    (update: (current: DataTableState) => Partial<DataTableState>) =>
      setStateValue((current) => ({ ...current, ...update(current), page: 1 })),
    [],
  );
  const setQuery = useCallback(
    (update: (query: DataTableQuery) => Partial<DataTableQuery>) =>
      toFirstPage((current) => ({
        query: { ...current.query, ...update(current.query) },
      })),
    [toFirstPage],
  );

  const facetSource = remote ? undefined : localData;
  const getFacets = useCallback(
    (key: string) => {
      const column = columns.find((entry) => entry.id === key);
      if (!facetSource || !column) return undefined;
      return countFacets(facetSource, column);
    },
    [columns, facetSource],
  );

  const getAllRows = useCallback(async () => {
    if (!remote) return sorted;
    const response = await requestRef.current?.({
      ...requestParams,
      page: 1,
      pageSize: total ?? 10_000,
      signal: new AbortController().signal,
    });
    return response?.data ?? emptyRows;
  }, [remote, sorted, requestParams, total]);

  const pluginNames = useMemo(
    () => new Set(plugins.map((plugin) => plugin.name)),
    [plugins],
  );
  const hasPlugin = useCallback(
    (name: string) => pluginNames.has(name),
    [pluginNames],
  );

  const localDataRef = useRef(localData);
  localDataRef.current = localData;
  // Stable across renders, so parts can list them as hook dependencies.
  const actions = useMemo<TableActions<TData>>(
    () => ({
      setKeyword: (keyword) => setQuery(() => ({ keyword })),
      setSearch: (search) => setQuery(() => ({ search })),
      setFilter: (key, values) =>
        setQuery((query) => ({
          filters: { ...query.filters, [key]: values },
        })),
      setAdvanced: (advanced) => setQuery(() => ({ advanced })),
      resetQuery: () =>
        setQuery(() => ({
          keyword: "",
          filters: {},
          advanced: undefined,
          search: initialSearch(baseColumns),
        })),
      toggleSort: (key, multi = false) =>
        toFirstPage((current) => {
          const existing = current.sort.find((item) => item.key === key);
          const others = multi
            ? current.sort.filter((item) => item.key !== key)
            : [];
          if (!existing) return { sort: [...others, { key, order: "asc" }] };
          if (existing.order === "asc")
            return { sort: [...others, { key, order: "desc" }] };
          return { sort: others };
        }),
      setSort: (sort) => toFirstPage(() => ({ sort })),
      setPage: (page) => setStateValue((current) => ({ ...current, page })),
      setPageSize: (pageSize) => toFirstPage(() => ({ pageSize })),
      resetColumns: () => setColumnStateValue(defaultColumnState),
      toggleExpanded: (id) =>
        setExpanded((current) => {
          const next = new Set(current);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
        }),
      setRows: (next) => {
        if (remote) {
          setRemoteResult((current) => ({ ...current, rows: next }));
          return next;
        }
        const merged = mergeRows(localDataRef.current, next);
        setLocalOverride({ source: data, rows: merged });
        return merged;
      },
      reload: () => setReloadToken((token) => token + 1),
      reset: () => {
        setStateValue(initialStateRef.current);
        setSelected(new Map());
      },
    }),
    [setQuery, toFirstPage, baseColumns, defaultColumnState, remote, data],
  );

  const instance: DataTableInstance<TData> = {
    columns,
    visibleColumns: orderColumns(columns, columnState),
    rows,
    total,
    pageCount,
    hasNextPage,
    loading: remote ? loadingRequest : !!options.loading,
    error,
    remote,
    state,
    columnState,
    density,
    view,
    selection,
    labels,
    locale: labels.locale,
    plugins,
    features,
    paginated: paginated && !features.dragSort,
    pageSizes,
    defaultPageSize,
    hasPlugin,
    getRowId,
    setState,
    setColumnState: setColumnStateValue,
    setDensity,
    setView,
    isExpanded: (id) => expanded.has(id),
    getFacets,
    getAllRows,
    ...actions,
  };

  return instance;
}

"use client";

import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "cn";
import { CalendarIcon } from "lucide-react";
import { type ReactNode, useMemo, useState } from "react";
import type { DateRange, Matcher, PropsBase } from "react-day-picker";
import {
  type DateTimeLabelOverrides,
  type DateTimeLabels,
  type DateTimeParts,
  dateFromParts,
  dateTimeLayout,
  formatLocalDate,
  localeHourCycle,
  localeWeekStart,
  orderRange,
  partsFromDate,
  resolveDateTimeLabels,
  type TimeOptions,
} from "@/lib/date-time";
import {
  DateTimeField,
  DateTimeWheels,
  PickerFrame,
  PickerOverlay,
  pickerLayout,
  TimeWheels,
  useControllable,
  WheelsGroup,
} from "@/lib/date-time-field";
import type { GlassProps } from "@/lib/glass/with-glass";

export interface DatePickerPreset {
  label: ReactNode;
  /** A function is read on click, so "Last 7 days" stays current. */
  value: DateRange | (() => DateRange);
}

interface DatePickerBaseProps extends GlassProps {
  /** Adds time segments and wheels; the value keeps its time of day. */
  showTime?: boolean | TimeOptions;
  /** A BCP 47 tag for segment order, names, week start and the hour cycle. */
  locale?: string;
  labels?: DateTimeLabelOverrides;
  /** Earliest and latest selectable days. */
  min?: Date;
  max?: Date;
  /** Days that cannot be picked, in react-day-picker matcher form. */
  disabledDates?: Matcher | Matcher[];
  disabled?: boolean;
  /** Submits local `yyyy-mm-dd` (or `yyyy-mm-ddThh:mm`) through hidden inputs. */
  name?: string;
  /** Lands on the first segment. */
  id?: string;
  className?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  "aria-invalid"?: boolean;
  /** Further Calendar props, such as `captionLayout` or `numberOfMonths`. */
  calendarProps?: Partial<PropsBase>;
}

export interface DatePickerSingleProps extends DatePickerBaseProps {
  mode?: "single";
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (value: Date | undefined) => void;
}

export interface DatePickerRangeProps extends DatePickerBaseProps {
  mode: "range";
  value?: DateRange;
  defaultValue?: DateRange;
  onValueChange?: (value: DateRange | undefined) => void;
  /** Quick ranges listed beside the calendar. */
  presets?: readonly DatePickerPreset[];
}

export type DatePickerProps = DatePickerSingleProps | DatePickerRangeProps;

function usePickerSetup(props: DatePickerBaseProps) {
  const { locale, showTime, min, max, disabledDates } = props;
  const options = typeof showTime === "object" ? showTime : undefined;
  const { seconds, step } = options ?? {};
  const hourCycle = useMemo(
    () => options?.hourCycle ?? localeHourCycle(locale),
    [options?.hourCycle, locale],
  );
  // Keyed on primitives, so an inline `showTime={{ … }}` keeps its memo.
  const timed = Boolean(showTime);
  const time = useMemo(
    () => (timed ? { seconds, step } : undefined),
    [timed, seconds, step],
  );
  const labels = useMemo(
    () => resolveDateTimeLabels(locale, props.labels),
    [locale, props.labels],
  );
  const layout = useMemo(
    () =>
      dateTimeLayout(locale, {
        date: true,
        time: Boolean(time),
        seconds: time?.seconds,
        hourCycle,
      }),
    [locale, time, hourCycle],
  );
  const calendar = useMemo(() => {
    const month = new Intl.DateTimeFormat(locale, {
      year: "numeric",
      month: "long",
    });
    const weekday = new Intl.DateTimeFormat(locale, { weekday: "narrow" });
    const shortMonth = new Intl.DateTimeFormat(locale, { month: "short" });
    const matchers = [
      ...(min ? [{ before: min }] : []),
      ...(max ? [{ after: max }] : []),
      ...[disabledDates ?? []].flat(),
    ];
    return {
      weekStartsOn: localeWeekStart(locale),
      startMonth: min,
      endMonth: max,
      disabled: matchers.length ? matchers : undefined,
      formatters: {
        formatCaption: (date: Date) => month.format(date),
        formatWeekdayName: (date: Date) => weekday.format(date),
        formatMonthDropdown: (date: Date) => shortMonth.format(date),
      },
      ...props.calendarProps,
    };
  }, [locale, min, max, disabledDates, props.calendarProps]);
  const fieldProps = {
    layout,
    hourCycle,
    locale,
    labels,
    step: time?.step,
    disabled: props.disabled,
  };
  const wheelProps = {
    hourCycle,
    locale,
    labels,
    seconds: time?.seconds,
    step: time?.step,
    disabled: props.disabled,
  };
  return { time, labels, calendar, fieldProps, wheelProps };
}

/** A picked day keeps the time already chosen; a new one starts at 00:00. */
function onDay(day: Date, previous: Date | undefined) {
  if (!previous) return day;
  return dateFromParts({
    ...partsFromDate(previous),
    year: day.getFullYear(),
    month: day.getMonth() + 1,
    day: day.getDate(),
  });
}

/** Time wheels on a day not picked yet start from today. */
function atTime(parts: DateTimeParts, previous: Date | undefined) {
  const base = previous ?? new Date(new Date().setHours(0, 0, 0, 0));
  return dateFromParts({ ...partsFromDate(base), ...parts });
}

const sameRange = (a: DateRange | undefined, b: DateRange | undefined) =>
  a?.from?.getTime() === b?.from?.getTime() &&
  a?.to?.getTime() === b?.to?.getTime();

const toParts = (date: Date | undefined) =>
  date ? partsFromDate(date) : undefined;
const toDate = (parts: DateTimeParts | undefined) =>
  parts ? dateFromParts(parts) : undefined;
const isInvalid = (date: Date | undefined, min?: Date, max?: Date) =>
  Boolean(
    date &&
      ((min && date < new Date(new Date(min).setHours(0, 0, 0, 0))) ||
        (max && date > new Date(new Date(max).setHours(23, 59, 59, 999)))),
  );

type PickerSetup = ReturnType<typeof usePickerSetup>;

// Beside the calendar on wider screens, taking the width the popover has
// beyond it, so the wheels sit centred on a band across the column.
const timeColumn = "flex flex-1 flex-col justify-center gap-3 border-s p-1.5";
// A lone time beside the calendar shows as many rows as it fits, even in a
// five-week month, so the panel keeps its height between months.
const besideCalendarRows = 11;

interface PhoneWheelsProps {
  value: Date | undefined;
  onValueChange: (value: Date) => void;
  setup: PickerSetup;
  locale: string | undefined;
  labels: DateTimeLabels;
  min?: Date;
  max?: Date;
  disabled?: boolean;
}

/** On phones, wheels replace the calendar: the date and its time in a row. */
function PhoneWheels({
  value,
  onValueChange,
  setup,
  locale,
  labels,
  min,
  max,
  disabled,
}: PhoneWheelsProps) {
  const { time, wheelProps } = setup;
  return (
    <DateTimeWheels
      className="w-full"
      aria-label={labels.chooseDate}
      value={value}
      onValueChange={onValueChange}
      time={
        time && {
          hourCycle: wheelProps.hourCycle,
          seconds: time.seconds,
          step: time.step,
        }
      }
      locale={locale}
      labels={labels}
      min={min}
      max={max}
      disabled={disabled}
    />
  );
}

function SingleDatePicker(props: DatePickerSingleProps) {
  const setup = usePickerSetup(props);
  const { time, labels, calendar, fieldProps, wheelProps } = setup;
  const [value, setValue] = useControllable(props, "value" in props);
  const [open, setOpen] = useState(false);
  const mobile = useIsMobile();
  const invalid =
    props["aria-invalid"] || isInvalid(value, props.min, props.max);
  return (
    <>
      <PickerFrame
        labels={labels}
        disabled={props.disabled}
        invalid={invalid}
        glass={props.glass}
        frosted={props.frosted}
        className={props.className}
        onClear={value ? () => setValue(undefined) : undefined}
        overlay={
          <PickerOverlay
            open={open}
            onOpenChange={setOpen}
            icon={<CalendarIcon />}
            label={labels.chooseDate}
            doneLabel={labels.done}
            disabled={props.disabled}
            glass={props.glass}
            frosted={props.frosted}
          >
            {mobile ? (
              <PhoneWheels
                value={value}
                onValueChange={setValue}
                setup={setup}
                locale={props.locale}
                labels={labels}
                min={props.min}
                max={props.max}
                disabled={props.disabled}
              />
            ) : (
              <div className="flex">
                <Calendar
                  className="bg-transparent"
                  {...calendar}
                  mode="single"
                  selected={value}
                  defaultMonth={value}
                  onSelect={(day) => {
                    if (!day) return;
                    setValue(onDay(day, value));
                    if (!time) setOpen(false);
                  }}
                />
                {time && (
                  <div className={timeColumn}>
                    <TimeWheels
                      {...wheelProps}
                      rows={besideCalendarRows}
                      aria-label={labels.chooseTime}
                      value={toParts(value)}
                      onValueChange={(parts) => setValue(atTime(parts, value))}
                    />
                  </div>
                )}
              </div>
            )}
          </PickerOverlay>
        }
      >
        <DateTimeField
          {...fieldProps}
          id={props.id}
          aria-label={props["aria-label"]}
          aria-labelledby={props["aria-labelledby"]}
          aria-invalid={invalid || undefined}
          value={toParts(value)}
          onValueChange={(parts) => setValue(toDate(parts))}
        />
      </PickerFrame>
      {props.name && (
        <input
          type="hidden"
          name={props.name}
          value={value ? formatLocalDate(value, time) : ""}
        />
      )}
    </>
  );
}

function RangeDatePicker(props: DatePickerRangeProps) {
  const setup = usePickerSetup(props);
  const { time, labels, calendar, fieldProps, wheelProps } = setup;
  const [value, setValue] = useControllable(props, "value" in props);
  // Typing and wheels leave the ends as entered until focus leaves the field
  // or the panel closes, so a swap never moves the end being set. Until then
  // a reversed range is shown here but never reported, and only while the
  // value it was entered over still stands: a new value replaces it.
  const [held, setHeld] = useState<{ range: DateRange; over?: DateRange }>();
  const reversed = held && sameRange(held.over, value) ? held.range : undefined;
  // Clearing remounts the fields, so no half-typed segment outlives it.
  const [clears, setClears] = useState(0);
  const [open, setOpen] = useState(false);
  const mobile = useIsMobile();
  const layout = pickerLayout(mobile);
  const from = (reversed ?? value)?.from;
  const to = (reversed ?? value)?.to;
  const report = (range: Partial<DateRange>) => {
    setHeld(undefined);
    setValue(
      range.from || range.to ? { from: range.from, to: range.to } : undefined,
    );
  };
  const update = (next: Partial<DateRange>, order = true) => {
    const edges = {
      from: "from" in next ? next.from : from,
      to: "to" in next ? next.to : to,
    };
    if (!order && edges.from && edges.to && edges.from > edges.to) {
      setHeld({ range: { from: edges.from, to: edges.to }, over: value });
      return;
    }
    report(
      order
        ? orderRange(edges.from, edges.to, (a, b) => a.getTime() - b.getTime())
        : edges,
    );
  };
  const putInOrder = () => {
    if (reversed) update({});
  };
  const edgeLabel = (end: "from" | "to") =>
    end === "from" ? labels.start : labels.end;
  const invalid =
    props["aria-invalid"] ||
    isInvalid(from, props.min, props.max) ||
    isInvalid(to, props.min, props.max);
  const field = (end: "from" | "to", date: Date | undefined, id?: string) => (
    <DateTimeField
      key={`${end}-${clears}`}
      {...fieldProps}
      id={id}
      className={end === "from" ? "flex-none pe-1" : "flex-none ps-1"}
      aria-label={[props["aria-label"], edgeLabel(end)]
        .filter(Boolean)
        .join(" ")}
      aria-invalid={invalid || undefined}
      value={toParts(date)}
      onValueChange={(parts) => update({ [end]: toDate(parts) }, false)}
    />
  );
  const presets = props.presets && props.presets.length > 0 && (
    <div className={layout.presets}>
      {props.presets.map((preset, index) => (
        <Button
          // biome-ignore lint/suspicious/noArrayIndexKey: Presets are an ordered list without ids.
          key={index}
          variant="ghost"
          size="sm"
          className="justify-start"
          onClick={() => {
            const range =
              typeof preset.value === "function"
                ? preset.value()
                : preset.value;
            update({ from: range.from, to: range.to });
            setOpen(false);
          }}
        >
          {preset.label}
        </Button>
      ))}
    </div>
  );
  return (
    <>
      <PickerFrame
        labels={labels}
        disabled={props.disabled}
        invalid={invalid}
        glass={props.glass}
        frosted={props.frosted}
        // A range is as wide as its two dates, not the row it sits in.
        className={cn("w-fit max-w-full", props.className)}
        onClear={
          value || reversed
            ? () => {
                setClears((count) => count + 1);
                report({});
              }
            : undefined
        }
        overlay={
          <PickerOverlay
            open={open}
            onOpenChange={(next) => {
              setOpen(next);
              if (!next) putInOrder();
            }}
            icon={<CalendarIcon />}
            label={labels.chooseDate}
            doneLabel={labels.done}
            disabled={props.disabled}
            glass={props.glass}
            frosted={props.frosted}
          >
            {mobile ? (
              <div className={layout.panel}>
                {presets}
                <div className={layout.ends}>
                  {(["from", "to"] as const).map((end) => (
                    <WheelsGroup key={end} caption={edgeLabel(end)}>
                      <PhoneWheels
                        // An end not set yet starts at the other end's day.
                        value={end === "from" ? (from ?? to) : (to ?? from)}
                        onValueChange={(date) => update({ [end]: date }, false)}
                        setup={setup}
                        locale={props.locale}
                        labels={labels}
                        min={props.min}
                        max={props.max}
                        disabled={props.disabled}
                      />
                    </WheelsGroup>
                  ))}
                </div>
              </div>
            ) : (
              <div className={layout.panel}>
                {presets}
                <Calendar
                  className="bg-transparent"
                  numberOfMonths={2}
                  {...calendar}
                  mode="range"
                  resetOnSelect
                  selected={{ from, to }}
                  defaultMonth={from}
                  onSelect={(range) => {
                    update({
                      from: range?.from && onDay(range.from, from),
                      to: range?.to && onDay(range.to, to),
                    });
                    if (!time && range?.from && range.to) setOpen(false);
                  }}
                />
                {time && (
                  <div className={timeColumn}>
                    {(["from", "to"] as const).map((end) => {
                      const date = end === "from" ? from : to;
                      return (
                        <WheelsGroup key={end} caption={edgeLabel(end)}>
                          <TimeWheels
                            {...wheelProps}
                            aria-label={`${edgeLabel(end)} ${labels.chooseTime}`}
                            value={toParts(date)}
                            onValueChange={(parts) =>
                              update(
                                { [end]: atTime(parts, date ?? from) },
                                false,
                              )
                            }
                          />
                        </WheelsGroup>
                      );
                    })}
                  </div>
                )}
              </div>
            )}
          </PickerOverlay>
        }
      >
        {/* biome-ignore lint/a11y/useSemanticElements: The two ends form one labelled group without fieldset layout. */}
        <div
          role="group"
          aria-label={props["aria-label"]}
          aria-labelledby={props["aria-labelledby"]}
          // Scrolls sideways when narrower than both dates, with no scrollbar
          className="flex min-w-0 flex-1 items-center overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          onBlur={(event) => {
            if (event.currentTarget.contains(event.relatedTarget)) return;
            putInOrder();
          }}
        >
          {field("from", from, props.id)}
          <span aria-hidden="true" className="text-muted-foreground">
            ~
          </span>
          {field("to", to)}
        </div>
      </PickerFrame>
      {props.name &&
        [value?.from, value?.to].map((date, index) => (
          <input
            // biome-ignore lint/suspicious/noArrayIndexKey: The start and end inputs keep their order.
            key={index}
            type="hidden"
            name={props.name}
            value={date ? formatLocalDate(date, time) : ""}
          />
        ))}
    </>
  );
}

/**
 * A typed, segmented date field with a calendar panel: one day or a range,
 * optionally with a time of day.
 */
function DatePicker(props: DatePickerProps) {
  if (props.mode === "range") return <RangeDatePicker {...props} />;
  return <SingleDatePicker {...props} />;
}

