}

function SelectInput({
  className,
  children,
  disabled = false,
  showTrigger,
  showClear = false,
  ...props
}: SelectPrimitive.Input.Props & {
  showTrigger?: boolean;
  showClear?: boolean;
}) {
  const inContent = React.useContext(SelectContentContext);
