"use client";

import { cn } from "cn";
import {
  type AnimationPlaybackControls,
  animate,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import {
  type ComponentProps,
  type PointerEvent,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { type GlassProps, withGlass } from "@/lib/glass/with-glass";
import { createTickPlayer } from "@/lib/tick-sound";
import {
  type FeedbackOption,
  useFeedback,
  useFeedbackSettings,
} from "@/components/ui/feedback";

export type WheelPickerOption = string | { label: string; value: string };
export interface WheelPickerProps
  extends GlassProps,
    Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "children"> {
  options: readonly WheelPickerOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** An odd number of visible rows, from 3 to 11. */
  visibleCount?: number;
  itemHeight?: number;
  disabled?: boolean;
  /**
   * Selection haptic and tick per row crossed; follows `FeedbackProvider` when
   * unset. The tick never plays before user interaction.
   */
  feedback?: FeedbackOption;
  /** Includes the selected value in native form submission. */
  name?: string;
}

// Physics tuned for an iOS-like flick: the wheel coasts in whole-row units,
// then settles on a row with a small bounce.
/** Rows per ms², how fast a flick bleeds off; lower coasts further. */
const deceleration = 0.00042;
/** Rows per ms; caps a hard fling. */
const maxVelocity = 0.18;
/** Recent drag, in ms, averaged into a release velocity. */
const velocityWindow = 90;
/** Rows per pixel of wheel delta. */
const wheelSensitivity = 0.012;
/** Wheel idle time, in ms, before snapping to a row. */
const wheelSettle = 110;
/** Movement, in px, below which a press is a tap on its option. */
const tapSlop = 4;
// Overshoots the row by a few percent, then settles: the detent's bounce.
const back = 1.35;
const easeOutBack = (progress: number) =>
  1 + (back + 1) * (progress - 1) ** 3 + back * (progress - 1) ** 2;

const optionValue = (option: WheelPickerOption) =>
  typeof option === "string" ? option : option.value;
const optionLabel = (option: WheelPickerOption) =>
  typeof option === "string" ? option : option.label;
const clamp = (value: number, last: number) =>
  Math.max(0, Math.min(last, value));

type Drag = {
  pointer: number | "touch";
  y: number;
  position: number;
  option?: number;
  moved: boolean;
  samples: [y: number, time: number][];
};

function WheelPickerImplementation({
  options,
  value,
  defaultValue,
  onValueChange,
  visibleCount = 7,
  itemHeight = 36,
  disabled = false,
  feedback,
  name,
  className,
  style,
  ref: forwardedRef,
  onKeyDown,
  onClick,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onLostPointerCapture,
  "aria-label": ariaLabel = "Options",
  ...props
}: WheelPickerProps) {
  const id = useId();
  const reducedMotion = useReducedMotion();
  const controlled = value !== undefined;
  const [internal, setInternal] = useState(defaultValue);
  const selectedValue = controlled ? value : internal;
  const index = Math.max(
    0,
    options.findIndex((option) => optionValue(option) === selectedValue),
  );
  const selected = options[index];
  const unavailable = disabled || !options.length;
  const rowHeight = Number.isFinite(itemHeight) ? Math.max(24, itemHeight) : 36;
  const rows = Number.isFinite(visibleCount)
    ? Math.min(11, Math.max(3, Math.floor(visibleCount / 2) * 2 + 1))
    : 7;
  // The outer rows tilt away and fill only the middle of a row-per-slot box,
  // so the drum is as tall as its projection: two radii, plus a little for
  // the edge rows' own height. A flat, reduced-motion list needs every slot.
  const drumRadius = rowHeight / Math.tan(Math.PI / (rows + 1));
  const [grabbing, setGrabbing] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const input = useRef<HTMLInputElement>(null);
  // The drum's position in rows: a float index both layers are painted from.
  const position = useMotionValue(index);
  const glide = useRef<AnimationPlaybackControls | undefined>(undefined);
  const wheelTimer = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined,
  );
  const tickPlayer = useRef<ReturnType<typeof createTickPlayer> | undefined>(
    undefined,
  );
  const lastTick = useRef(index);
  const trigger = useFeedback(feedback);
  const { sound } = useFeedbackSettings(feedback);
  const drag = useRef<Drag | undefined>(undefined);
  const live = useRef({
    options,
    index,
    controlled,
    unavailable,
    reducedMotion,
    rowHeight,
    rows,
    onValueChange,
    sound,
  });
  useLayoutEffect(() => {
    live.current = {
      options,
      index,
      controlled,
      unavailable,
      reducedMotion,
      rowHeight,
      rows,
      onValueChange,
      sound,
    };
  });

  const paint = useCallback(() => {
    const element = root.current;
    if (!element) return;
    const { rowHeight, rows, reducedMotion } = live.current;
    const at = position.get();
    const half = (rows - 1) / 2;
    const step = 90 / (half + 1);
    const radius = rowHeight / Math.tan((step * Math.PI) / 180);
    // The crisp band repeats the drum clipped to the centre row, painted with
    // the identical transform so the two copies register exactly.
    for (const item of element.querySelectorAll<HTMLElement>(
      "[data-wheel-item],[data-wheel-band-item]",
    )) {
      const distance =
        Number(item.dataset.wheelItem ?? item.dataset.wheelBandItem) - at;
      const angle = Math.max(-90, Math.min(90, distance * step));
      const radians = (angle * Math.PI) / 180;
      // Reduced motion lays the rows flat: a drum row stays upright and its
      // option slides, a band row slides itself.
      const flat = `translateY(${distance * rowHeight}px)`;
      const drum = `translate3d(0,${Math.sin(radians) * radius}px,${(Math.cos(radians) - 1) * radius}px) rotateX(${-angle}deg)`;
      const band = item.dataset.wheelBandItem !== undefined;
      let transform = drum;
      if (reducedMotion) transform = band ? flat : "none";
      if (item.style.transform !== transform) item.style.transform = transform;
      const slot = band ? undefined : item.parentElement;
      const offset = reducedMotion ? flat : "";
      if (slot && slot.style.transform !== offset)
        slot.style.transform = offset;
      const visibility =
        !reducedMotion && Math.abs(distance) > half + 0.5
          ? "hidden"
          : "visible";
      // Write only on change, so a drag never restyles every row per frame.
      if (item.style.visibility !== visibility)
        item.style.visibility = visibility;
    }
  }, [position]);

  const prepareAudio = useCallback(() => {
    if (!live.current.sound || live.current.unavailable) return;
    tickPlayer.current ??= createTickPlayer();
    tickPlayer.current.prepare();
  }, []);

  // Ticks follow the nearest row as the drum crosses it, independently of the
  // value committed once it settles.
  const tickAt = useCallback(
    (at: number) => {
      const state = live.current;
      const row = clamp(Math.round(at), state.options.length - 1);
      if (row === lastTick.current) return;
      lastTick.current = row;
      if (state.unavailable) return;
      if (state.sound) tickPlayer.current?.play();
      // The picker voices its own tick, so feedback adds only the haptic.
      trigger("selection", false);
    },
    [trigger],
  );

  // A silent glide follows rows without sounding them.
  const silentGlide = useRef(false);
  useEffect(
    () =>
      position.on("change", (at) => {
        paint();
        if (silentGlide.current)
          lastTick.current = clamp(
            Math.round(at),
            live.current.options.length - 1,
          );
        else tickAt(at);
      }),
    [position, paint, tickAt],
  );

  const stop = useCallback(() => {
    glide.current?.stop();
    glide.current = undefined;
    silentGlide.current = false;
  }, []);

  /** Moves the drum to a row; a silent move never ticks on the way. */
  const settle = useCallback(
    (
      target: number,
      {
        duration = 0.3,
        silent = false,
        onSettle,
      }: { duration?: number; silent?: boolean; onSettle?: () => void } = {},
    ) => {
      stop();
      if (live.current.reducedMotion || position.get() === target) {
        silentGlide.current = silent;
        position.jump(target);
        silentGlide.current = false;
        paint();
        onSettle?.();
        return;
      }
      silentGlide.current = silent;
      const controls = animate(position, target, {
        duration,
        ease: easeOutBack,
      });
      glide.current = controls;
      controls.then(() => {
        if (glide.current !== controls) return;
        glide.current = undefined;
        silentGlide.current = false;
        onSettle?.();
      });
    },
    [position, paint, stop],
  );

  /** Returns a resting drum to the selection the parent keeps. */
  const realign = useCallback(() => {
    if (drag.current || glide.current) return;
    if (Math.round(position.get()) !== live.current.index)
      settle(live.current.index, { silent: true });
  }, [position, settle]);

  /** Commits a row; the parent owns controlled selection, including a refusal. */
  const choose = useCallback(
    (target: number) => {
      const state = live.current;
      const option = state.options[clamp(target, state.options.length - 1)];
      if (state.unavailable || !option) return;
      if (target !== state.index) {
        if (!state.controlled) setInternal(optionValue(option));
        state.onValueChange?.(optionValue(option));
      }
      requestAnimationFrame(realign);
    },
    [realign],
  );

  /** A keyboard or tap selection ticks once, then glides silently. */
  const select = useCallback(
    (target: number) => {
      const state = live.current;
      const row = clamp(target, state.options.length - 1);
      if (row !== state.index) tickAt(row);
      settle(row, { silent: true, onSettle: realign });
      choose(row);
    },
    [choose, realign, settle, tickAt],
  );

  // Follow the selection, geometry and preference unless a gesture runs.
  // biome-ignore lint/correctness/useExhaustiveDependencies: Geometry and preference changes repaint the same selection through the live refs.
  useLayoutEffect(() => {
    if (drag.current || glide.current) {
      paint();
      return;
    }
    if (Math.round(position.get()) === index) {
      paint();
      return;
    }
    settle(index, { duration: 0.26, silent: true });
  }, [index, options, settle, rowHeight, rows, reducedMotion]);

  useEffect(() => {
    const form = input.current?.form;
    if (!form || controlled) return;
    const reset = () => {
      setInternal(defaultValue);
      const target = Math.max(
        0,
        options.findIndex((option) => optionValue(option) === defaultValue),
      );
      settle(target, { silent: true });
    };
    form.addEventListener("reset", reset);
    return () => form.removeEventListener("reset", reset);
  }, [controlled, defaultValue, options, settle]);

  const beginDrag = useCallback(
    (pointer: Drag["pointer"], y: number, option?: number) => {
      stop();
      clearTimeout(wheelTimer.current);
      prepareAudio();
      drag.current = {
        pointer,
        y,
        position: position.get(),
        option,
        moved: false,
        samples: [[y, performance.now()]],
      };
      setGrabbing(true);
    },
    [position, prepareAudio, stop],
  );

  const moveDrag = useCallback(
    (y: number) => {
      const active = drag.current;
      if (!active) return;
      active.samples.push([y, performance.now()]);
      if (active.samples.length > 8) active.samples.shift();
      if (Math.abs(y - active.y) >= tapSlop) active.moved = true;
      const last = live.current.options.length - 1;
      let next = active.position + (active.y - y) / live.current.rowHeight;
      // Rubber-band past either end.
      if (next < 0) next *= 0.3;
      else if (next > last) next = last + (next - last) * 0.3;
      position.set(next);
    },
    [position],
  );

  const endDrag = useCallback(
    (cancelled: boolean) => {
      const active = drag.current;
      if (!active) return;
      drag.current = undefined;
      setGrabbing(false);
      const { options, rowHeight, index } = live.current;
      const last = options.length - 1;
      if (cancelled) {
        settle(index, { silent: true });
        return;
      }
      if (!active.moved && active.option !== undefined) {
        select(active.option);
        return;
      }
      // Average velocity over the last moments of the drag, so a single noisy
      // frame cannot make an even flick catch or slip.
      let velocity = 0;
      const samples = active.samples;
      const latest = samples[samples.length - 1];
      const reference =
        samples.find(([, time]) => latest[1] - time <= velocityWindow) ??
        samples[0];
      const elapsed = latest[1] - reference[1];
      if (elapsed > 0)
        velocity = Math.max(
          -maxVelocity,
          Math.min(
            maxVelocity,
            (reference[0] - latest[0]) / rowHeight / elapsed,
          ),
        );
      const from = position.get();
      if (from < 0 || from > last) {
        const target = clamp(Math.round(from), last);
        settle(target, { duration: 0.26, onSettle: () => choose(target) });
        return;
      }
      const coast =
        ((velocity * velocity) / (2 * deceleration)) * Math.sign(velocity);
      const target = clamp(Math.round(from + coast), last);
      // A long, bounce-tipped settle reads as momentum coasting to rest.
      const duration =
        Math.max(
          280,
          Math.min(1700, Math.sqrt(Math.abs(target - from)) * 300 + 240),
        ) / 1000;
      settle(target, { duration, onSettle: () => choose(target) });
    },
    [choose, position, select, settle],
  );

  useEffect(() => {
    const cancel = () => endDrag(true);
    if (unavailable) cancel();
    window.addEventListener("blur", cancel);
    return () => window.removeEventListener("blur", cancel);
  }, [unavailable, endDrag]);

  // Touch and wheel bind natively and non-passively, so the drum can keep the
  // page from scrolling while it spins.
  useEffect(() => {
    const element = root.current;
    if (!element || unavailable) return;
    const optionAt = (target: EventTarget | null) => {
      const option =
        target instanceof Element
          ? target.closest<HTMLElement>("[data-wheel-option]")
          : null;
      return option ? Number(option.dataset.wheelOption) : undefined;
    };
    const touchStart = (event: TouchEvent) => {
      const touch = event.touches[0];
      if (touch && event.touches.length === 1)
        beginDrag("touch", touch.clientY, optionAt(event.target));
    };
    const touchMove = (event: TouchEvent) => {
      const touch = event.touches[0];
      if (!touch || drag.current?.pointer !== "touch") return;
      event.preventDefault();
      moveDrag(touch.clientY);
    };
    const touchEnd = (event: TouchEvent) => {
      if (drag.current?.pointer !== "touch") return;
      endDrag(event.type === "touchcancel");
    };
    // The wheel drives the drum continuously, then snaps once it goes idle.
    const wheel = (event: WheelEvent) => {
      if (event.defaultPrevented) return;
      event.preventDefault();
      prepareAudio();
      stop();
      const last = live.current.options.length - 1;
      const pixels = event.deltaMode === 1 ? event.deltaY * 16 : event.deltaY;
      position.set(clamp(position.get() + pixels * wheelSensitivity, last));
      clearTimeout(wheelTimer.current);
      wheelTimer.current = setTimeout(() => {
        const target = clamp(Math.round(position.get()), last);
        settle(target, { duration: 0.24, onSettle: () => choose(target) });
      }, wheelSettle);
    };
    element.addEventListener("touchstart", touchStart, { passive: true });
    element.addEventListener("touchmove", touchMove, { passive: false });
    element.addEventListener("touchend", touchEnd);
    element.addEventListener("touchcancel", touchEnd);
    element.addEventListener("wheel", wheel, { passive: false });
    return () => {
      element.removeEventListener("touchstart", touchStart);
      element.removeEventListener("touchmove", touchMove);
      element.removeEventListener("touchend", touchEnd);
      element.removeEventListener("touchcancel", touchEnd);
      element.removeEventListener("wheel", wheel);
    };
  }, [
    unavailable,
    beginDrag,
    moveDrag,
    endDrag,
    prepareAudio,
    stop,
    position,
    settle,
    choose,
  ]);

  useEffect(
    () => () => {
      glide.current?.stop();
      clearTimeout(wheelTimer.current);
      tickPlayer.current?.dispose();
      tickPlayer.current = undefined;
    },
    [],
  );

  useEffect(() => {
    if (sound && !unavailable) return;
    tickPlayer.current?.dispose();
    tickPlayer.current = undefined;
  }, [sound, unavailable]);

  const releasePointer = (event: PointerEvent<HTMLDivElement>) => {
    if (root.current?.hasPointerCapture(event.pointerId))
      root.current.releasePointerCapture(event.pointerId);
  };

  const rowClassName =
    "flex h-full items-center justify-center truncate px-3 font-medium [backface-visibility:hidden]";

  return (
    <div
      {...props}
      ref={(node) => {
        root.current = node;
        if (typeof forwardedRef === "function") {
          const cleanup = forwardedRef(node);
          if (cleanup)
            return () => {
              root.current = null;
              cleanup();
            };
        } else if (forwardedRef) forwardedRef.current = node;
      }}
      data-slot="wheel-picker"
      // The drum owns vertical drags, so a bottom sheet around it stays put.
      data-bottom-sheet-no-drag=""
      role="listbox"
      aria-label={ariaLabel}
      aria-disabled={unavailable || undefined}
      aria-activedescendant={selected ? `${id}-${index}` : undefined}
      tabIndex={unavailable ? -1 : 0}
      className={cn(
        "relative isolate w-40 min-w-0 touch-none select-none overflow-hidden rounded-3xl bg-card text-foreground text-sm outline-none ring-1 ring-foreground/10 [-webkit-touch-callout:none] focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-3",
        !unavailable && (grabbing ? "cursor-grabbing" : "cursor-grab"),
        unavailable && "opacity-50",
        className,
      )}
      style={{
        ...style,
        height: reducedMotion
          ? rowHeight * rows
          : Math.ceil(2 * drumRadius + rowHeight / 4),
        perspective: reducedMotion ? undefined : 1000,
      }}
      onClick={(event) => {
        onClick?.(event);
        // Mouse and touch taps select on release; this is the keyboardless
        // path for assistive technology activating an option.
        if (
          event.defaultPrevented ||
          unavailable ||
          event.detail !== 0 ||
          drag.current
        )
          return;
        const option = (event.target as Element).closest<HTMLElement>(
          "[data-wheel-option]",
        );
        if (option) {
          prepareAudio();
          select(Number(option.dataset.wheelOption));
        }
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || unavailable) return;
        const targets: Record<string, number> = {
          ArrowUp: index - 1,
          ArrowDown: index + 1,
          Home: 0,
          End: options.length - 1,
          PageUp: index - rows,
          PageDown: index + rows,
        };
        const target = targets[event.key];
        if (target === undefined) return;
        event.preventDefault();
        prepareAudio();
        clearTimeout(wheelTimer.current);
        select(clamp(target, options.length - 1));
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (
          event.defaultPrevented ||
          unavailable ||
          event.pointerType === "touch" ||
          event.button !== 0
        )
          return;
        event.preventDefault();
        root.current?.focus({ preventScroll: true });
        const option = (event.target as Element).closest<HTMLElement>(
          "[data-wheel-option]",
        );
        beginDrag(
          event.pointerId,
          event.clientY,
          option ? Number(option.dataset.wheelOption) : undefined,
        );
        root.current?.setPointerCapture(event.pointerId);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (event.defaultPrevented || drag.current?.pointer !== event.pointerId)
          return;
        moveDrag(event.clientY);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        if (drag.current?.pointer !== event.pointerId) return;
        releasePointer(event);
        endDrag(false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        if (drag.current?.pointer !== event.pointerId) return;
        releasePointer(event);
        endDrag(true);
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event);
        if (drag.current?.pointer === event.pointerId) endDrag(true);
      }}
    >
      {/* Dimmed rows on the drum; each sits on its accessible option. */}
      <div
        role="presentation"
        className="absolute inset-x-0 top-1/2 [transform-style:preserve-3d]"
        style={{ marginTop: -rowHeight / 2 }}
      >
        {options.map((option, position) => (
          <div
            id={`${id}-${position}`}
            key={optionValue(option)}
            role="option"
            tabIndex={-1}
            data-wheel-option={position}
            aria-label={optionLabel(option)}
            aria-selected={index === position}
            className="absolute inset-x-0 top-0 [transform-style:preserve-3d]"
            style={{ height: rowHeight }}
          >
            <span
              aria-hidden="true"
              data-wheel-item={position}
              className={cn(rowClassName, "text-muted-foreground")}
            >
              {optionLabel(option)}
            </span>
          </div>
        ))}
      </div>
      {/* The centre row drawn crisp: the same drum clipped to one row, with a
          perspective centred where the main drum's is. */}
      <div
        aria-hidden="true"
        data-slot="wheel-picker-band"
        className="pointer-events-none absolute inset-x-1 top-1/2 z-10 -translate-y-1/2 overflow-hidden rounded-xl bg-foreground/5"
        style={{
          height: rowHeight,
          perspective: reducedMotion ? undefined : 1000,
        }}
      >
        <div className="absolute inset-x-[-0.25rem] top-0 [transform-style:preserve-3d]">
          {options.map((option, position) => (
            <span
              key={optionValue(option)}
              data-wheel-band-item={position}
              className={cn(
                rowClassName,
                "absolute inset-x-0 top-0 text-foreground",
              )}
              style={{ height: rowHeight }}
            >
              {optionLabel(option)}
            </span>
          ))}
        </div>
      </div>
      {name && (
        <input
          ref={input}
          type="hidden"
          name={name}
          value={selected ? optionValue(selected) : ""}
          disabled={disabled}
        />
      )}
    </div>
  );
}

const WheelPicker = withGlass(WheelPickerImplementation);

export { WheelPicker };

"use client";

import {
  type AnimationPlaybackControls,
  animate,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import * as React from "react";
import {
  type BottomSheetDetents,
  type BottomSheetLayout,
  type BottomSheetSize,
  bottomSheetDefaults,
  bottomSheetFrame,
  bottomSheetLayout,
  createVelocityTracker,
  resolveBottomSheetRelease,
} from "@/lib/bottom-sheet";

type BottomSheetControllerOptions = {
  open: boolean;
  size: BottomSheetSize;
  expandable: boolean;
  setSize: (size: BottomSheetSize) => void;
  setShape: (shape: Pick<BottomSheetLayout, "expandable" | "full">) => void;
  close: () => void;
  isOpen: () => boolean;
  detents: BottomSheetDetents;
  keyboard: "resize" | "lift";
  footerMode: "adaptive" | "fixed";
  expandOnInputFocus: boolean;
  contentKey: React.Key | undefined;
};

type Drag = {
  source: "handle" | "body";
  pointerId: number | null;
  startX: number;
  startY: number;
  startExtent: number;
  extent: number;
  from: BottomSheetSize;
  /** Pending until the press moves far enough to tell a drag from a scroll. */
  mode: "pending" | "drag" | "native";
};

/** Heights read once per measurement, so drag frames never read layout. */
type Chrome = { header: number; footer: number; natural: number };

const textField =
  'input:not([type="checkbox"],[type="radio"],[type="range"],[type="button"],[type="submit"],[type="reset"],[type="file"],[type="color"]),textarea,select,[contenteditable=""],[contenteditable="true"]';
// Fields, sliders, the footer and marked regions keep their own gestures.
const ownGesture = `${textField},input[type="range"],[role="slider"],[data-slot="bottom-sheet-footer"],[data-bottom-sheet-no-drag]`;
const handle =
  '[data-slot="bottom-sheet-header"],[data-slot="bottom-sheet-grabber"]';
const settleDelay = 500;
// A long, fully damped glide between sizes: one clean deceleration, the same
// curve the sheet enters with.
const drawerGlide = {
  duration: settleDelay / 1000,
  ease: [0.32, 0.72, 0, 1],
} as const;
// A release keeps the finger's speed, then settles without bouncing past the
// size it lands on.
const releaseSpring = {
  type: "spring",
  stiffness: 420,
  damping: 40,
  mass: 0.5,
} as const;

let progressRegistered = false;

/** Registers the progress variable as a number so it can animate. */
function registerProgress() {
  if (progressRegistered || typeof CSS === "undefined") return;
  progressRegistered = true;
  try {
    CSS.registerProperty?.({
      name: "--bottom-sheet-progress",
      syntax: "<number>",
      inherits: true,
      initialValue: "0",
    });
  } catch {
    // Already registered by another copy of the component.
  }
}

function part(container: HTMLElement, slot: "header" | "body" | "footer") {
  return container.querySelector<HTMLElement>(
    `:scope > [data-slot="bottom-sheet-${slot}"]`,
  );
}

/** The body scrolls, unless the whole container does when space is short. */
function scrollElement(container: HTMLElement) {
  if (container.dataset.scroll === "container") return container;
  return part(container, "body") ?? container;
}

function resetScroll(container: HTMLElement) {
  container.scrollTop = 0;
  const body = part(container, "body");
  if (body) body.scrollTop = 0;
}

// Offset and scroll heights are rounded whole pixels; summed, they can come
// up a fraction short of fractional content, which then overflows a sheet
// sized to fit it and shows a needless scrollbar. Heights here are exact,
// and the total is rounded up.
const exactHeight = (element: HTMLElement) =>
  element.getBoundingClientRect().height;

// A collapsed header still reserves its full height in the layout.
function headerHeight(header: HTMLElement | null) {
  if (!header) return 0;
  if (header.hasAttribute("data-collapsed") && header.dataset.naturalHeight)
    return Number(header.dataset.naturalHeight);
  return exactHeight(header);
}

/** The body's content height, exact even while it scrolls or is clipped. */
function bodyHeight(body: HTMLElement) {
  const last = body.lastElementChild;
  if (!last) return body.scrollHeight;
  const bottom =
    last.getBoundingClientRect().bottom -
    body.getBoundingClientRect().top +
    body.scrollTop +
    (Number.parseFloat(getComputedStyle(body).paddingBottom) || 0);
  return Math.max(body.scrollHeight, bottom);
}

function measureChrome(popup: HTMLElement, container: HTMLElement): Chrome {
  const styles = getComputedStyle(container);
  let natural =
    (Number.parseFloat(styles.paddingTop) || 0) +
    (Number.parseFloat(styles.paddingBottom) || 0) +
    popup.offsetHeight -
    popup.clientHeight;
  for (const child of Array.from(container.children)) {
    if (!(child instanceof HTMLElement)) continue;
    const slot = child.dataset.slot;
    if (slot === "bottom-sheet-header") natural += headerHeight(child);
    else if (slot === "bottom-sheet-body") natural += bodyHeight(child);
    else natural += exactHeight(child);
  }
  const footer = part(container, "footer");
  return {
    header: Math.ceil(headerHeight(part(container, "header"))),
    footer: footer ? Math.ceil(exactHeight(footer)) : 0,
    natural: Math.ceil(natural),
  };
}

// Keeps a drag going outside the sheet; the pointer may already be gone.
function capture(element: HTMLElement, pointerId: number) {
  try {
    element.setPointerCapture(pointerId);
  } catch {
    // Released before the drag began.
  }
}

function keyboardInset() {
  const viewport = window.visualViewport;
  if (!viewport) return 0;
  const hidden = window.innerHeight - viewport.height - viewport.offsetTop;
  return Math.max(0, Math.round(hidden));
}

/** Coalesces calls into one per animation frame. */
function perFrame(callback: () => void) {
  let frame = 0;
  const schedule = () => {
    if (frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      callback();
    });
  };
  schedule.cancel = () => cancelAnimationFrame(frame);
  return schedule;
}

/**
 * Measures the sheet into sizes, paints its frame through CSS variables
 * and runs its drag, wheel and focus gestures.
 */
export function useBottomSheetController(
  options: BottomSheetControllerOptions,
) {
  const { open, size, expandable, setSize, setShape, contentKey } = options;
  const [popup, setPopup] = React.useState<HTMLDivElement | null>(null);
  const [settled, setSettled] = React.useState(false);
  const containerRef = React.useRef<HTMLDivElement>(null);
  const overlayRef = React.useRef<HTMLDivElement>(null);
  const probeRef = React.useRef<HTMLDivElement>(null);
  const optionsRef = React.useRef(options);
  optionsRef.current = options;
  const layoutRef = React.useRef<BottomSheetLayout>({
    heights: { default: 0, lg: 0 },
    expandable: false,
    full: false,
  });
  const chromeRef = React.useRef<Chrome>({ header: 0, footer: 0, natural: 0 });
  const dragRef = React.useRef<Drag | null>(null);
  const reducedMotion = useReducedMotion();
  // The visible height; every frame of a drag or glide is painted from it.
  const extent = useMotionValue(0);
  const glideRef = React.useRef<{
    controls: AnimationPlaybackControls;
    to: number;
  } | null>(null);
  // An opening sheet lands at its first size and enters with Base UI.
  const placedRef = React.useRef(false);
  if (!open) placedRef.current = false;

  const extentOf = React.useCallback(
    (target: BottomSheetSize) => layoutRef.current.heights[target],
    [],
  );

  // Only writes CSS variables, so it can run on every pointer move.
  const paint = React.useCallback(
    (extent: number) => {
      if (!popup) return;
      const frame = bottomSheetFrame(extent, layoutRef.current);
      const dismiss = Math.min(1, frame.offset / Math.max(1, frame.height));
      popup.style.setProperty("--bottom-sheet-height", `${frame.height}px`);
      popup.style.setProperty("--bottom-sheet-offset", `${frame.offset}px`);
      popup.style.setProperty("--bottom-sheet-progress", `${frame.progress}`);
      const overlay = overlayRef.current?.style;
      overlay?.setProperty("--bottom-sheet-progress", `${frame.progress}`);
      overlay?.setProperty("--bottom-sheet-dismiss", `${dismiss}`);
    },
    [popup],
  );

  React.useEffect(() => extent.on("change", paint), [extent, paint]);

  const stopGlide = React.useCallback(() => {
    glideRef.current?.controls.stop();
    glideRef.current = null;
    popup?.removeAttribute("data-gliding");
    overlayRef.current?.removeAttribute("data-gliding");
  }, [popup]);

  /** Moves to a height: in place, along a glide, or carrying a release. */
  const moveTo = React.useCallback(
    (to: number, velocity?: number) => {
      if (glideRef.current?.to === to) return;
      stopGlide();
      if (!placedRef.current || reducedMotion || extent.get() === to) {
        // A sheet measured before it has a size is not placed yet.
        placedRef.current = to > 0;
        extent.jump(to);
        paint(to);
        return;
      }
      // CSS transitions stand aside while Motion paints every frame.
      popup?.setAttribute("data-gliding", "");
      overlayRef.current?.setAttribute("data-gliding", "");
      const controls = animate(
        extent,
        to,
        velocity === undefined
          ? drawerGlide
          : { ...releaseSpring, velocity: velocity * 1000 },
      );
      glideRef.current = { controls, to };
      controls.then(() => {
        if (glideRef.current?.controls === controls) stopGlide();
      });
    },
    [extent, paint, popup, reducedMotion, stopGlide],
  );

  React.useEffect(() => stopGlide, [stopGlide]);

  // Chooses what scrolls: nothing until the sheet may scroll, then the body,
  // or the whole container when an adaptive footer leaves too little room.
  const scrollableRef = React.useRef(false);
  const flowsRef = React.useRef(false);
  const applyScroll = React.useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    let scroll = "none";
    if (scrollableRef.current) scroll = "body";
    if (scrollableRef.current && (flowsRef.current || !part(container, "body")))
      scroll = "container";
    container.dataset.scroll = scroll;
  }, []);

  // Rests at a size: paints it, then lets the footer flow if it must.
  const rest = React.useCallback(
    (target: BottomSheetSize, velocity?: number) => {
      const height = extentOf(target);
      moveTo(height, velocity);
      const { header, footer } = chromeRef.current;
      flowsRef.current =
        optionsRef.current.footerMode === "adaptive" &&
        footer > 0 &&
        height - header - footer < bottomSheetDefaults.minimumBody;
      applyScroll();
    },
    [moveTo, extentOf, applyScroll],
  );

  const measure = React.useCallback(() => {
    const container = containerRef.current;
    const { isOpen, keyboard, detents } = optionsRef.current;
    if (!popup || !container || !isOpen()) return;
    const viewportHeight =
      popup.parentElement?.clientHeight ?? window.innerHeight;
    const room = viewportHeight - (probeRef.current?.offsetHeight ?? 0);
    const inset = keyboardInset();
    popup.style.setProperty("--bottom-sheet-keyboard", `${inset}px`);
    const chrome = measureChrome(popup, container);
    chromeRef.current = chrome;
    const layout = bottomSheetLayout({
      available: keyboard === "lift" ? room : room - inset,
      natural: chrome.natural,
      chrome: chrome.header + chrome.footer,
      detents,
    });
    // Lifting keeps the height, but never past the space above the keyboard.
    const limit = Math.max(0, room - inset);
    layoutRef.current = {
      ...layout,
      heights: {
        default: Math.min(layout.heights.default, limit),
        lg: Math.min(layout.heights.lg, limit),
      },
    };
    setShape({ expandable: layout.expandable, full: layout.full });
    if (dragRef.current?.mode !== "drag") rest(optionsRef.current.size);
  }, [popup, rest, setShape]);

  // Measure before the first paint, then once per frame after content,
  // viewport or keyboard changes.
  React.useLayoutEffect(() => {
    registerProgress();
    const container = containerRef.current;
    if (!popup || !container || !open) return;
    measure();
    const schedule = perFrame(measure);
    // Widening the sheet resizes every child; only height changes matter.
    const heights = new WeakMap<Element, number>();
    const resize = new ResizeObserver((entries) => {
      let changed = false;
      for (const entry of entries) {
        const height = entry.contentRect.height;
        if (heights.get(entry.target) !== height) changed = true;
        heights.set(entry.target, height);
      }
      if (changed) schedule();
    });
    const observe = () => {
      resize.disconnect();
      for (const child of Array.from(container.children)) resize.observe(child);
      if (popup.parentElement) resize.observe(popup.parentElement);
    };
    observe();
    const mutation = new MutationObserver(() => {
      observe();
      schedule();
    });
    mutation.observe(container, { childList: true });
    const events = new AbortController();
    const { signal } = events;
    window.visualViewport?.addEventListener("resize", schedule, { signal });
    window.visualViewport?.addEventListener("scroll", schedule, { signal });
    return () => {
      schedule.cancel();
      resize.disconnect();
      mutation.disconnect();
      events.abort();
    };
  }, [popup, open, measure]);

  // A new detent policy needs a fresh layout.
  // biome-ignore lint/correctness/useExhaustiveDependencies: the policy props trigger a measurement.
  React.useLayoutEffect(measure, [
    measure,
    options.detents,
    options.keyboard,
    options.footerMode,
  ]);

  // Settle at the size; the body scrolls only once expansion finishes.
  React.useLayoutEffect(() => {
    if (dragRef.current?.mode !== "drag") rest(size);
    if (size === "default" && containerRef.current)
      resetScroll(containerRef.current);
    setSettled(false);
    const timer = window.setTimeout(() => setSettled(true), settleDelay);
    return () => window.clearTimeout(timer);
  }, [size, rest]);

  // A new content key starts over at the default size, at the top.
  const contentKeyRef = React.useRef(contentKey);
  React.useEffect(() => {
    if (Object.is(contentKeyRef.current, contentKey)) return;
    contentKeyRef.current = contentKey;
    if (containerRef.current) resetScroll(containerRef.current);
    setSize("default");
  }, [contentKey, setSize]);

  const scrollable = !expandable || (size === "lg" && settled);
  React.useLayoutEffect(() => {
    scrollableRef.current = scrollable;
    applyScroll();
  }, [scrollable, applyScroll]);

  // Keep a focused field in view once the body can scroll.
  React.useEffect(() => {
    const active = document.activeElement;
    if (
      scrollable &&
      active instanceof HTMLElement &&
      active.matches(textField) &&
      containerRef.current?.contains(active)
    )
      active.scrollIntoView({ block: "nearest" });
  }, [scrollable]);

  // Drags: the header and grabber move the sheet with any pointer. Touch on
  // the body moves it while the body cannot scroll, or pulls it down from the
  // top of a scrolled body.
  React.useEffect(() => {
    const container = containerRef.current;
    if (!popup || !container) return;
    const tracker = createVelocityTracker();
    const events = new AbortController();
    const { signal } = events;
    let suppressClickUntil = 0;

    function begin(
      source: Drag["source"],
      x: number,
      y: number,
      pointerId: number | null,
    ) {
      const from = optionsRef.current.size;
      // A press during a glide catches the sheet where it is.
      const current = glideRef.current ? extent.get() : extentOf(from);
      dragRef.current = {
        source,
        pointerId,
        startX: x,
        startY: y,
        startExtent: current,
        extent: current,
        from,
        mode: "pending",
      };
      tracker.reset();
      tracker.add(-y, performance.now());
    }
    // Vertical movement past the threshold drags the sheet, unless it starts
    // a scroll in a body that can scroll.
    function decide(drag: Drag, dx: number, dy: number): Drag["mode"] {
      const threshold = bottomSheetDefaults.dragThreshold;
      if (Math.abs(dy) < threshold || Math.abs(dy) <= Math.abs(dx))
        return Math.abs(dx) > threshold ? "native" : "pending";
      if (drag.source === "handle") return "drag";
      if (!container || container.dataset.scroll === "none") return "drag";
      const pullsFromTop = scrollElement(container).scrollTop <= 0 && dy > 0;
      return pullsFromTop ? "drag" : "native";
    }
    function move(drag: Drag, x: number, y: number, time: number) {
      tracker.add(-y, time);
      const dy = y - drag.startY;
      if (drag.mode === "pending") {
        drag.mode = decide(drag, x - drag.startX, dy);
        if (drag.mode !== "drag") return false;
        popup?.setAttribute("data-dragging", "");
        overlayRef.current?.setAttribute("data-dragging", "");
      }
      drag.extent = Math.min(
        drag.startExtent - dy,
        layoutRef.current.heights.lg,
      );
      stopGlide();
      extent.jump(drag.extent);
      return true;
    }
    function target(drag: Drag, velocity: number) {
      const layout = layoutRef.current;
      // An upward swipe on the body at the default size expands even when it
      // is short.
      const swipedUp =
        drag.source === "body" &&
        drag.from === "default" &&
        layout.expandable &&
        drag.extent - layout.heights.default > 16 &&
        velocity > -bottomSheetDefaults.flickVelocity;
      if (swipedUp) return "lg";
      return resolveBottomSheetRelease({
        extent: drag.extent,
        velocity,
        layout,
        from: drag.from,
      });
    }
    function end(drag: Drag, time: number, cancelled: boolean) {
      dragRef.current = null;
      if (drag.mode !== "drag") return;
      popup?.removeAttribute("data-dragging");
      overlayRef.current?.removeAttribute("data-dragging");
      suppressClickUntil = performance.now() + 80;
      const velocity = cancelled ? 0 : tracker.velocity(time);
      const next = target(drag, velocity);
      if (next !== "closed") {
        rest(next, velocity);
        if (next !== optionsRef.current.size) setSize(next);
        return;
      }
      optionsRef.current.close();
      // A parent that keeps the sheet open gets it back at its size.
      requestAnimationFrame(() => {
        if (optionsRef.current.isOpen()) rest(optionsRef.current.size);
      });
    }

    popup.addEventListener(
      "pointerdown",
      (event) => {
        const element = event.target as Element | null;
        if (event.button !== 0 || dragRef.current) return;
        if (!element?.closest(handle) || element.closest(textField)) return;
        begin("handle", event.clientX, event.clientY, event.pointerId);
      },
      { signal },
    );
    popup.addEventListener(
      "pointermove",
      (event) => {
        const drag = dragRef.current;
        if (drag?.pointerId !== event.pointerId || drag.mode === "native")
          return;
        const pending = drag.mode === "pending";
        const dragging = move(
          drag,
          event.clientX,
          event.clientY,
          event.timeStamp,
        );
        if (dragging && pending) capture(popup, event.pointerId);
      },
      { signal },
    );
    const release = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (drag?.pointerId === event.pointerId)
        end(drag, event.timeStamp, event.type === "pointercancel");
    };
    popup.addEventListener("pointerup", release, { signal });
    popup.addEventListener("pointercancel", release, { signal });
    // A finished drag must not also press what it started on.
    popup.addEventListener(
      "click",
      (event) => {
        if (performance.now() > suppressClickUntil) return;
        event.preventDefault();
        event.stopPropagation();
      },
      { capture: true, signal },
    );
    container.addEventListener(
      "touchstart",
      (event) => {
        const touch = event.touches[0];
        const element = event.target as Element | null;
        if (event.touches.length !== 1 || !touch || dragRef.current) return;
        if (!element || element.closest(handle) || element.closest(ownGesture))
          return;
        begin("body", touch.clientX, touch.clientY, null);
      },
      { passive: true, signal },
    );
    container.addEventListener(
      "touchmove",
      (event) => {
        const drag = dragRef.current;
        const touch = event.touches[0];
        if (drag?.source !== "body" || drag.mode === "native" || !touch) return;
        const dragging = move(
          drag,
          touch.clientX,
          touch.clientY,
          event.timeStamp,
        );
        if (dragging && event.cancelable) event.preventDefault();
      },
      { passive: false, signal },
    );
    const touchEnd = (event: TouchEvent) => {
      const drag = dragRef.current;
      if (drag?.source === "body")
        end(drag, event.timeStamp, event.type === "touchcancel");
    };
    container.addEventListener("touchend", touchEnd, { signal });
    container.addEventListener("touchcancel", touchEnd, { signal });
    return () => events.abort();
  }, [popup, rest, extentOf, setSize, extent, stopGlide]);

  // Wheel, focus and header state while the body scrolls.
  React.useEffect(() => {
    const container = containerRef.current;
    if (!popup || !container) return;
    const events = new AbortController();
    const { signal } = events;
    let wheelUntil = 0;
    const canExpand = () =>
      layoutRef.current.expandable && optionsRef.current.size === "default";

    // An expandable sheet at the default size expands on the first scroll down
    // and absorbs the rest of that wheel gesture.
    container.addEventListener(
      "wheel",
      (event) => {
        const now = performance.now();
        const expands = canExpand() && event.deltaY > 0;
        if (now >= wheelUntil && !expands) return;
        wheelUntil = now + 250;
        if (event.cancelable) event.preventDefault();
        if (expands) setSize("lg");
      },
      { passive: false, signal },
    );
    container.addEventListener(
      "focusin",
      (event) => {
        const element = event.target as Element | null;
        if (
          optionsRef.current.expandOnInputFocus &&
          canExpand() &&
          element?.matches(textField)
        )
          setSize("lg");
      },
      { signal },
    );
    const updateHeader = perFrame(() => {
      const header = part(container, "header");
      if (header?.dataset.collapseOnScroll !== "true") return;
      const scroller = scrollElement(container);
      const top = scroller.scrollTop;
      const collapsed = header.hasAttribute("data-collapsed");
      // Hysteresis keeps a short scroll range from toggling back and forth.
      const range = scroller.scrollHeight - scroller.clientHeight;
      if (!collapsed && top > 24 && range > 48) {
        header.dataset.naturalHeight = `${header.offsetHeight}`;
        header.setAttribute("data-collapsed", "");
      }
      if (collapsed && top < 4) header.removeAttribute("data-collapsed");
    });
    // Scroll events do not bubble, so listen while they pass down to the body.
    container.addEventListener("scroll", updateHeader, {
      capture: true,
      passive: true,
      signal,
    });
    return () => {
      updateHeader.cancel();
      events.abort();
    };
  }, [popup, setSize]);

  return { popupRef: setPopup, containerRef, overlayRef, probeRef };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { type FeedbackOption, useFeedback } from "@/components/ui/feedback";

type ClipboardStatus = "idle" | "pending" | "copied" | "error";
/** English defaults. Pass overrides or `clipboardLabelsZhCN` through `labels`. */
const clipboardLabels = {
  copy: "Copy",
  pending: "Copying…",
  copied: "Copied",
  copyFailed: "Copy failed",
};
const clipboardLabelsZhCN: ClipboardLabels = {
  copy: "复制",
  pending: "正在复制…",
  copied: "已复制",
  copyFailed: "复制失败",
};
type ClipboardLabels = Partial<typeof clipboardLabels>;
type ClipboardOptions = {
  disabled?: boolean;
  resetDelay?: number;
  onCopy?: (value: string) => void;
  onCopyError?: (error: Error) => void;
  /** Haptics for a finished copy; follows `FeedbackProvider` when unset. */
  feedback?: FeedbackOption;
  labels?: ClipboardLabels;
};
type ClipboardControllerOptions = Omit<
  ClipboardOptions,
  "disabled" | "feedback" | "labels"
> & {
  writeText: (value: string) => Promise<void>;
  onStatusChange: (status: ClipboardStatus) => void;
};

// The controller owns each async attempt, so late results never update a newer
// value, a second attempt, or an unmounted component.
function createClipboardController(options: ClipboardControllerOptions) {
  let active = true;
  let pending = false;
  let attempt = 0;
  let copiedValue: string | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const clear = () => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  const reset = () => {
    attempt++;
    pending = false;
    copiedValue = undefined;
    clear();
    if (active) options.onStatusChange("idle");
  };
  return {
    activate() {
      active = true;
    },
    reset,
    synchronize(value: string) {
      // An uncontrolled input can synchronize after copying its live DOM value.
      if (value !== copiedValue) reset();
    },
    dispose() {
      active = false;
      attempt++;
      pending = false;
      copiedValue = undefined;
      clear();
    },
    async copy(value: string): Promise<boolean> {
      if (!active || pending) return false;
      const current = ++attempt;
      copiedValue = value;
      pending = true;
      clear();
      options.onStatusChange("pending");
      try {
        await options.writeText(value);
      } catch (reason) {
        if (!active || current !== attempt) return false;
        pending = false;
        const error =
          reason instanceof Error ? reason : new Error(String(reason));
        options.onStatusChange("error");
        options.onCopyError?.(error);
        return false;
      }
      if (!active || current !== attempt) return false;
      pending = false;
      options.onStatusChange("copied");
      const delay = options.resetDelay ?? 1500;
      timer = setTimeout(
        () => {
          timer = undefined;
          if (active && current === attempt) options.onStatusChange("idle");
        },
        Number.isFinite(delay) ? Math.max(0, delay) : 1500,
      );
      options.onCopy?.(value);
      return true;
    },
  };
}

function useClipboard(value: string, options: ClipboardOptions = {}) {
  const [status, setStatus] = useState<ClipboardStatus>("idle");
  const optionsRef = useRef(options);
  optionsRef.current = options;
  const trigger = useFeedback(options.feedback);
  const [controller] = useState(() =>
    createClipboardController({
      writeText: async (text) => {
        if (
          typeof navigator === "undefined" ||
          !navigator.clipboard?.writeText
        ) {
          throw new Error(
            "Clipboard access is unavailable. Select and copy the text manually.",
          );
        }
        await navigator.clipboard.writeText(text);
      },
      onStatusChange: setStatus,
      onCopy: (text) => {
        trigger("success");
        optionsRef.current.onCopy?.(text);
      },
      onCopyError: (error) => {
        trigger("error");
        optionsRef.current.onCopyError?.(error);
      },
      get resetDelay() {
        return optionsRef.current.resetDelay;
      },
    }),
  );
  useEffect(() => {
    controller.activate();
    return () => controller.dispose();
  }, [controller]);
  useEffect(() => {
    if (options.disabled) controller.reset();
    else controller.synchronize(value);
  }, [controller, value, options.disabled]);
  const text = { ...clipboardLabels, ...options.labels };
  return {
    status,
    /** The label for the current status: the copy action while idle. */
    message: {
      idle: text.copy,
      pending: text.pending,
      copied: text.copied,
      error: text.copyFailed,
    }[status],
    copy: (text = value) =>
      options.disabled ? Promise.resolve(false) : controller.copy(text),
    reset: controller.reset,
  };
}

export type { ClipboardLabels, ClipboardOptions, ClipboardStatus };
export {
  clipboardLabels,
  clipboardLabelsZhCN,
  createClipboardController,
  useClipboard,
};

import { useLayoutEffect, useState } from "react";

/**
 * Whether a media query matches. `undefined` on the server and until the first
 * layout effect, so a component can render something that suits every size
 * until it knows.
 */
export function useMediaQuery(query: string) {
  const [matches, setMatches] = useState<boolean>();
  useLayoutEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const mql = window.matchMedia(query);
    const onChange = () => setMatches(mql.matches);
    mql.addEventListener("change", onChange);
    onChange();
    return () => mql.removeEventListener("change", onChange);
  }, [query]);
  return matches;
}

import { useMediaQuery } from "@/hooks/use-media-query";

const MOBILE_BREAKPOINT = 768;

export function useIsMobile() {
  return !!useMediaQuery(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
}

/** The sheet's detents: `"default"` rests at about half height, `"lg"` fills it. */
export type BottomSheetSize = "default" | "lg";

/**
 * `"auto"` adds the `"lg"` size only when content outgrows `"default"`,
 * `"always"` keeps both, and `false` sizes a single detent to content.
 */
export type BottomSheetDetents = "auto" | "always" | false;

export type BottomSheetLayout = {
  /** Visible height at each size; both are equal for a single detent. */
  heights: Record<BottomSheetSize, number>;
  /** The sheet can grow from `"default"` to `"lg"`. */
  expandable: boolean;
  /** The sheet fills the available height, so it reads as expanded. */
  full: boolean;
};

export const bottomSheetDefaults = {
  /** The default size takes at most half the available height, as on iOS. */
  defaultRatio: 0.5,
  /** Body space the default size must keep beside its header and footer. */
  minimumBody: 80,
  /** Movement before a press becomes a drag. */
  dragThreshold: 6,
  /** Release velocity, in px/ms, that moves one size in its direction. */
  flickVelocity: 0.3,
  /** Samples older than this, in ms, no longer count toward velocity. */
  velocityWindow: 100,
} as const;

/**
 * Resolves the height of each size from the space above the keyboard and
 * below the top safe area, the content's natural height and its header and
 * footer.
 */
export function bottomSheetLayout({
  available,
  natural,
  chrome,
  detents,
  defaultRatio = bottomSheetDefaults.defaultRatio,
  minimumBody = bottomSheetDefaults.minimumBody,
}: {
  available: number;
  natural: number;
  /** Header and footer height, which the default size must fit. */
  chrome: number;
  detents: BottomSheetDetents;
  defaultRatio?: number;
  minimumBody?: number;
}): BottomSheetLayout {
  const maximum = Math.max(0, available);
  const content = Math.max(0, natural);
  const single = (height: number): BottomSheetLayout => ({
    heights: { default: height, lg: height },
    expandable: false,
    full: height >= maximum - 1,
  });
  if (detents === false) return single(Math.min(content, maximum));
  const limit = maximum * defaultRatio;
  if (content > limit && limit < chrome + minimumBody)
    return single(Math.min(content, maximum));
  if (detents === "auto" && content <= limit) return single(content);
  const base = Math.min(content, limit);
  if (maximum - base <= 1) return single(maximum);
  return {
    heights: { default: base, lg: maximum },
    expandable: true,
    full: false,
  };
}

/**
 * Places a visible height: above the default size the sheet grows toward
 * `"lg"`, below it the sheet keeps its height and slides down toward closing.
 */
export function bottomSheetFrame(extent: number, layout: BottomSheetLayout) {
  const { heights, full } = layout;
  const visible = Math.min(extent, heights.lg);
  if (visible < heights.default)
    return {
      height: heights.default,
      offset: heights.default - Math.max(0, visible),
      progress: full ? 1 : 0,
    };
  return {
    height: visible,
    offset: 0,
    progress: frameProgress(visible, layout),
  };
}

/** 0 at the default size and 1 at `"lg"`; a full sheet stays 1. */
function frameProgress(visible: number, layout: BottomSheetLayout) {
  const { heights, expandable, full } = layout;
  if (full) return 1;
  const range = heights.lg - heights.default;
  if (!expandable || range <= 0) return 0;
  return (visible - heights.default) / range;
}

/** Distance below the default size at which a slow release closes. */
function bottomSheetCloseDistance(height: number) {
  return Math.min(Math.max(height * 0.35, 48), 180);
}

/**
 * Chooses where a drag settles. A flick moves one size in its direction;
 * otherwise the nearest size wins. A drag that began at `"lg"` cannot close
 * unless it was pulled below the default size first.
 */
export function resolveBottomSheetRelease({
  extent,
  velocity,
  layout,
  from,
  flickVelocity = bottomSheetDefaults.flickVelocity,
}: {
  /** Visible height at release. */
  extent: number;
  /** Upward velocity in px/ms; negative values move down. */
  velocity: number;
  layout: BottomSheetLayout;
  from: BottomSheetSize;
  flickVelocity?: number;
}): BottomSheetSize | "closed" {
  const { heights, expandable } = layout;
  const base = heights.default;
  const below = extent < base - 1;
  if (velocity >= flickVelocity) {
    if (expandable && extent >= base - 1) return "lg";
    return "default";
  }
  if (velocity <= -flickVelocity) {
    if (expandable && extent > base + 1) return "default";
    if (from === "lg" && expandable && !below) return "default";
    return below || extent <= base ? "closed" : "default";
  }
  if (below)
    return base - extent > bottomSheetCloseDistance(base)
      ? "closed"
      : "default";
  if (!expandable) return "default";
  return extent - base > (heights.lg - base) / 2 ? "lg" : "default";
}

/** Tracks recent pointer positions so a pause before release drops momentum. */
export function createVelocityTracker(
  window: number = bottomSheetDefaults.velocityWindow,
) {
  let samples: { time: number; position: number }[] = [];
  return {
    reset() {
      samples = [];
    },
    add(position: number, time: number) {
      samples.push({ position, time });
      while (samples.length > 2 && time - (samples[0]?.time ?? time) > window)
        samples.shift();
    },
    /** Velocity in px/ms along the tracked axis at `time`. */
    velocity(time: number) {
      const recent = samples.filter((sample) => time - sample.time <= window);
      const first = recent[0];
      const last = recent[recent.length - 1];
      if (!first || !last || last.time - first.time < 8) return 0;
      return (last.position - first.position) / (last.time - first.time);
    },
  };
}

